fn serve_vmess_kcp_tls(
    conn: &Arc<ferrox_core::kcp::Connection>,
    users: &crate::vmess::Users,
    freedom: bool,
    server: &ferrox_core::tls::TlsServerConfig,
    meter: crate::stats::Meter,
) {
    let Ok(mut tls) =
        ferrox_core::tls::accept(server, KcpIo::with_meter(Arc::clone(conn), meter.clone()))
    else {
        return;
    };
    if !shake_tls(&mut tls) {
        return;
    }
    let (reader, writer) = session_halves(tls, KcpIo::with_meter(Arc::clone(conn), meter));
    let closer = Arc::clone(conn);
    let close: Arc<dyn Fn() + Send + Sync> = Arc::new(move || closer.close());
    crate::vmess::serve_kcp(reader, writer, users, freedom, &close);
}

/// The `socks` front is also an HTTP proxy: a first byte that is not SOCKS4/5 goes to the
/// HTTP front, as the reference hands it to its own HTTP server.
fn serve_socks(mut client: Connection, out: &Outbound, accounts: &SocksAccounts) {
    let budget = budgets::handshake();
    let _ = client.set_read_timeout(Some(budget));
    let until = Instant::now() + budget;
    let mut first = [0u8; 1];
    match client.peek(&mut first) {
        Ok(0) | Err(_) => {
            let _ = client.set_read_timeout(None);
            reject_socks(&client);
            return;
        }
        Ok(_) => {}
    }
    if first[0] != 5 && first[0] != ferrox_core::socks::VERSION4 {
        let _ = client.set_read_timeout(None);
        serve_http(client, out, accounts);
        return;
    }
    let handshake = socks_request(&mut client, false, until, accounts);
    let _ = client.set_read_timeout(None);
    let Some(handshake) = handshake else {
        reject_socks(&client);
        return;
    };
    serve_socks_connected(client, out, &handshake);
}

fn reject_socks(client: &Connection) {
    crate::accesslog::record(
        client.peer_addr().ok(),
        false,
        &"unknown",
        None,
        "rejected",
        "",
    );
}

fn serve_socks_connected(mut client: Connection, out: &Outbound, handshake: &Handshake<'_>) {
    let email = handshake
        .account
        .as_ref()
        .map_or("", |account| account.email.as_str());
    let user = (!email.is_empty()).then_some(email);
    let level = handshake.account.as_ref().map(|account| account.level);
    if let Some(account) = &handshake.account {
        client = client
            .with_meter(crate::stats::user(&account.email, account.level))
            .with_policy(Some(crate::policy::flow(account.level)));
    }
    if handshake.cmd == 3 {
        return serve_socks_udp(client, out, user, level);
    }
    // The rules decide the lane first; a blocked flow is granted before it closes, so the front's reply is read.
    let destination = handshake.asked.authority();
    crate::accesslog::record(client.peer_addr().ok(), true, &destination, None, "", email);
    let first = match crate::sniff::current() {
        Some(sniffing) if sniffing.enabled() => None,
        _ => Some(out.resolved_lane_with_protocol(
            &handshake.asked,
            crate::router::Network::Tcp,
            Some(&client),
            FlowFacts {
                source: None,
                local: None,
                user,
                level,
                ..FlowFacts::default()
            },
        )),
    };
    if !matches!(
        first.as_ref().map_or(out, |(lane, _)| &**lane),
        Outbound::Foxy(_) | Outbound::Veepn(_)
    ) {
        let grant = match handshake.version {
            crate::socks::Version::V5 => Front::Socks.grant_line(),
            crate::socks::Version::V4 => ferrox_core::socks::grant4(),
        };
        if client.write_all(grant).is_err() {
            return;
        }
    }
    let (dial, out, tag) = match first {
        Some((lane, tag)) => (None, lane, tag),
        None => sniff_lane(out, &handshake.asked, &client, user, level),
    };
    let asked = dial.as_ref().unwrap_or(&handshake.asked);
    serve_connect(
        client,
        &out,
        asked,
        Front::Socks,
        &[],
        tag.as_deref(),
        FlowFacts {
            source: None,
            local: None,
            user,
            level,
            ..FlowFacts::default()
        },
    );
}

/// The device front's relay: the front layer's own dial, with the destination the
/// device's packet named.
///
/// The device does not know what an outbound is, so it asks for the dial every other
/// front reaches — the same `serve_connect` the socks and http fronts call, with the
/// same rules and the same grant.
pub(crate) fn serve_device_flow(
    client: Connection,
    out: &Outbound,
    dest: &Destination,
) -> std::io::Result<()> {
    let (dial, lane, tag) = sniff_lane(out, dest, &client, None, None);
    let dest = dial.as_ref().unwrap_or(dest);
    let ((), dial_report) = observe_dial(|| {
        serve_connect(
            client,
            &lane,
            dest,
            Front::Socks,
            &[],
            tag.as_deref(),
            FlowFacts::default(),
        );
    });
    match dial_report {
        Some(false) => Err(std::io::Error::new(
            std::io::ErrorKind::ConnectionRefused,
            "the proxy leg refused the device flow",
        )),
        _ => Ok(()),
    }
}

/// One mux `New` target for a flow the portal carries.
fn mux_destination(
    asked: &Destination,
    network: ferrox_core::mux::Network,
) -> ferrox_core::mux::Target<'_> {
    let addr = match asked {
        Destination::Name(host, _) => ferrox_core::addr::Addr::Name(host.as_bytes()),
        Destination::Address(address) => match address.ip() {
            std::net::IpAddr::V4(ip) => ferrox_core::addr::Addr::V4(ip.octets()),
            std::net::IpAddr::V6(ip) => ferrox_core::addr::Addr::V6(ip.octets()),
        },
    };
    ferrox_core::mux::Target {
        network,
        port: asked.port(),
        addr,
    }
}

/// A flow the rules routed to a portal: it rides one mux session the bridge opened, and the
/// portal never sees a socket for it.
fn serve_reverse_tcp(client: &Connection, portal: &crate::reverse::Portal, asked: &Destination) {
    let Some(session) = portal.pick() else {
        eprintln!(
            "reverse: portal `{}` has no live session, so the flow is closed",
            portal.tag()
        );
        return;
    };
    let target = mux_destination(asked, ferrox_core::mux::Network::Tcp);
    let Some((id, flow)) = session.open(target, ferrox_core::mux::DEFAULT_CAP as u32) else {
        return;
    };
    let (Ok(mut down), Ok(mut up)) = (client.try_clone(), client.try_clone()) else {
        session.end(id);
        return;
    };
    let sender = Arc::clone(&session);
    let reader = thread::spawn(move || {
        let mut chunk = [0u8; 8192];
        loop {
            match up.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    if !sender.send(id, &chunk[..n]) {
                        break;
                    }
                }
                Err(error) if is_timeout(&error) => {}
                Err(_) => break,
            }
        }
        sender.end(id);
    });
    while let Ok((data, _)) = flow.down.recv() {
        if down.write_all(&data).is_err() {
            break;
        }
    }
    let _ = down.shutdown(Shutdown::Both);
    session.end(id);
    let _ = reader.join();
}

/// Nothing carries the destination onward, so this lane is the one that has to redirect it,
/// resolve it by the configured strategy, and add the header or fragment the config asks for.
fn serve_connect_freedom(
    mut client: &Connection,
    freedom: &FreedomOut,
    asked: &Destination,
    prefix: &[u8],
) {
    let Some(target) = freedom_socket(freedom, asked) else {
        return;
    };
    if let Some(rule) = freedom.final_rule(crate::router::Network::Tcp, target.ip(), target.port())
    {
        if rule.action == FreedomRuleAction::Block {
            freedom_blackhole(client, rule);
            return;
        }
    }
    let Some(mut upstream) = dial_or_report(&target) else {
        return;
    };
    if freedom.proxy_protocol > 0 {
        let edges = Edges {
            local: client.peer_addr().ok(),
            peer: upstream.peer_addr().ok().or(Some(target)),
        };
        if ferrox_core::tls::write_proxy_protocol(&mut upstream, freedom.proxy_protocol, edges)
            .is_err()
        {
            return;
        }
    }
    let mut upstream = upstream.with_mask(freedom.fragment.as_deref());
    if !prefix.is_empty() && upstream.write_all(prefix).is_err() {
        return;
    }
    if !prefix.is_empty() && !http_head_has_body(prefix) {
        loop {
            let Some((mut head, at)) =
                read_http_head_kept(&mut upstream, HTTP_HEAD_LIMIT, budgets::head_arrival())
            else {
                return;
            };
            let tail = head.split_off(at);
            let interim = http_head_is_interim(&head);
            drop_invalid_header_names(&mut head);
            if client.write_all(&head).is_err() || client.write_all(&tail).is_err() {
                return;
            }
            if !interim {
                break;
            }
        }
    }
    relay_handoff(client, &upstream);
}

/// A request head that carries a body: the origin answers only after it arrives, so the direct leg
/// must relay before reading the response head or the two sides wait on each other.
fn http_head_has_body(head: &[u8]) -> bool {
    head.split(|byte| *byte == b'\n').skip(1).any(|line| {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        let Some(colon) = line.iter().position(|byte| *byte == b':') else {
            return false;
        };
        let (name, value) = line.split_at(colon);
        name.eq_ignore_ascii_case(b"transfer-encoding")
            || (name.eq_ignore_ascii_case(b"content-length")
                && value.iter().any(|byte| (b'1'..=b'9').contains(byte)))
    })
}

/// The reference's blocked target: the client is drained until the rule's wait ends, then closed.
fn freedom_blackhole(client: &Connection, rule: &FreedomFinalRule) {
    let delay = rule.delay();
    if delay.is_zero() {
        let _ = client.shutdown(Shutdown::Both);
        return;
    }
    let Some(until) = Instant::now().checked_add(delay) else {
        let _ = client.shutdown(Shutdown::Both);
        return;
    };
    let Ok(mut drain) = client.try_clone() else {
        thread::sleep(delay);
        return;
    };
    let mut buf = [0u8; 8192];
    while let Some(left) = until.checked_duration_since(Instant::now()) {
        let _ = drain.set_read_timeout(Some(left.min(Duration::from_secs(1))));
        match drain.read(&mut buf) {
            Ok(0) => break,
            Ok(_) => {}
            Err(error) if is_timeout(&error) => {}
            Err(_) => break,
        }
    }
    let _ = drain.shutdown(Shutdown::Both);
}

/// The decoys a UDP destination receives before its first real datagram; a DNS redirect keeps its
/// one packet clean, and a failed write ends the flow the way the reference's writer does.
fn send_freedom_noises(
    noises: &[FreedomNoise],
    skip_dns: bool,
    socket: &UdpSocket,
    dest: SocketAddr,
) -> bool {
    if noises.is_empty() || skip_dns {
        return true;
    }
    for noise in noises {
        if !noise.applies_to(dest.ip()) {
            continue;
        }
        let Some(packet) = noise.generate() else {
            return false;
        };
        if socket.send(&packet).is_err() {
            return false;
        }
        let delay = noise.delay();
        if !delay.is_zero() {
            thread::sleep(delay);
        }
    }
    true
}

/// The first payload waits behind its destination's decoys without stalling the association's
/// other lanes; the starter drains this queue once the last decoy has gone out.
#[derive(Default)]
struct FreedomNoiseGate {
    ready: bool,
    failed: bool,
    pending: Vec<Vec<u8>>,
}

impl FreedomNoiseGate {
    fn queue(&mut self, payload: &[u8]) {
        if self.pending.len() < UDP_BURST {
            self.pending.push(payload.to_vec());
        }
    }
}

/// The socket a freedom flow dials: its redirect first, then the family the strategy names.
fn freedom_socket(freedom: &FreedomOut, asked: &Destination) -> Option<SocketAddr> {
    let asked = freedom
        .redirect
        .as_ref()
        .map_or_else(|| asked.clone(), |redirect| redirect.apply(asked));
    match asked {
        Destination::Address(address) => Some(address),
        Destination::Name(host, port) => {
            if freedom.domain == FreedomDomain::AsIs {
                return resolve_endpoint(&host, port);
            }
            let ips = freedom_lookup(&host, port)?;
            if let Some(ip) = freedom.domain.pick(&ips) {
                return Some(SocketAddr::new(ip, port));
            }
            if freedom.domain.forces() {
                eprintln!(
                    "freedom: {host} did not resolve, and {} forces an address",
                    strategy_name(freedom.domain)
                );
                return None;
            }
            resolve_endpoint(&host, port)
        }
    }
}

fn freedom_lookup(host: &str, port: u16) -> Option<Vec<std::net::IpAddr>> {
    if let Some(resolver) = crate::dnsapp::installed() {
        return resolver.lookup(host).map(|(ips, _)| ips);
    }
    let addrs = if let Some(addrs) = cached_lookup(host, port) {
        addrs
    } else {
        let addrs = resolve_bounded(host, port, budgets::dial(), |host, port| {
            (host, port)
                .to_socket_addrs()
                .map(std::iter::Iterator::collect)
        })?;
        remember_lookup(host, port, &addrs)
    };
    Some(addrs.iter().map(std::net::SocketAddr::ip).collect())
}

fn strategy_name(domain: FreedomDomain) -> &'static str {
    match domain {
        FreedomDomain::AsIs => "AsIs",
        FreedomDomain::UseIp => "UseIP",
        FreedomDomain::UseIp4 => "UseIP4",
        FreedomDomain::UseIp6 => "UseIP6",
        FreedomDomain::UseIp46 => "UseIP46",
        FreedomDomain::UseIp64 => "UseIP64",
        FreedomDomain::ForceIp => "ForceIP",
        FreedomDomain::ForceIp4 => "ForceIP4",
        FreedomDomain::ForceIp6 => "ForceIP6",
        FreedomDomain::ForceIp46 => "ForceIP46",
        FreedomDomain::ForceIp64 => "ForceIP64",
    }
}

/// What `targetStrategy` takes a named target to before the protocol builds its request.
enum TargetPick {
    Keep,
    Address(Destination),
    Refuse,
}

/// The address the reference's outbound handler sends instead of a name, or the refusal a forced
/// strategy owes a name that answered no address of its family.
fn resolve_target(asked: &Destination, strategy: FreedomDomain) -> TargetPick {
    let Destination::Name(host, port) = asked else {
        return TargetPick::Keep;
    };
    let picked = freedom_lookup(host, *port).and_then(|ips| strategy.pick(&ips));
    match picked {
        Some(ip) => TargetPick::Address(Destination::Address(SocketAddr::new(ip, *port))),
        None if strategy.forces() => {
            eprintln!(
                "targetStrategy: {host} did not resolve, and {} forces an address",
                strategy_name(strategy)
            );
            TargetPick::Refuse
        }
        None => TargetPick::Keep,
    }
}

/// Sniff the client's first bytes, then pick the lane the reference would: the sniffed name is the
/// route target, and the original address stays the dial target under `routeOnly`. A sniffed HTTP
/// head also carries the attributes an `attrs` rule reads, whether or not it named a host.
fn sniff_lane<'a>(
    out: &'a Outbound,
    asked: &Destination,
    client: &Connection,
    user: Option<&str>,
    level: Option<u32>,
) -> (
    Option<Destination>,
    Picked<'a>,
    Option<std::borrow::Cow<'a, str>>,
) {
    let Some(sniffing) = crate::sniff::current() else {
        let facts = FlowFacts {
            source: None,
            local: None,
            user,
            level,
            ..FlowFacts::default()
        };
        let (lane, tag) = out.resolved_lane_with_protocol(
            asked,
            crate::router::Network::Tcp,
            Some(client),
            facts,
        );
        return (None, lane, tag);
    };
    let (found, pairs) = sniffing.inspect(
        asked,
        crate::router::Network::Tcp,
        client,
        out.wants_attrs(),
    );
    let attrs = (!pairs.is_empty()).then(|| crate::router::Attributes::from_pairs(&pairs));
    let facts = FlowFacts {
        source: None,
        local: None,
        user,
        level,
        attrs: attrs.as_ref(),
        original: Some(asked),
        ..FlowFacts::default()
    };
    let Some(found) = found else {
        let (lane, tag) = out.resolved_lane_with_protocol(
            asked,
            crate::router::Network::Tcp,
            Some(client),
            facts,
        );
        return (None, lane, tag);
    };
    let route = found
        .override_destination
        .then(|| Destination::Name(found.domain.clone(), asked.port()));
    let dial = if sniffing.should_dial_override(&found) {
        route.clone()
    } else {
        None
    };
    let facts = FlowFacts {
        source: None,
        local: None,
        protocol: Some(found.protocol),
        original: Some(asked),
        route: if dial.is_none() { route.as_ref() } else { None },
        ..facts
    };
    let (resolved, tag) = out.resolved_lane_with_protocol(
        route.as_ref().unwrap_or(asked),
        crate::router::Network::Tcp,
        Some(client),
        facts,
    );
    (dial, resolved, tag)
}

/// A loopback outbound's own sniffer runs before its named inbound sees the flow, as the
/// reference's second dispatch does: the sniffed name routes, and only a dial override changes
/// the target `routeOnly` keeps at the original address.
#[allow(clippy::type_complexity)]
fn loopback_sniffed(
    loopback: &LoopbackOut,
    asked: &Destination,
    client: &Connection,
    want_attrs: bool,
) -> (
    Option<Destination>,
    Option<Destination>,
    Option<&'static str>,
    Vec<(String, String)>,
) {
    let Some(sniffing) = loopback.sniffing.as_ref() else {
        return (None, None, None, Vec::new());
    };
    let (found, pairs) = sniffing.inspect(asked, crate::router::Network::Tcp, client, want_attrs);
    let Some(found) = found else {
        return (None, None, None, pairs);
    };
    let route = found
        .override_destination
        .then(|| Destination::Name(found.domain.clone(), asked.port()));
    let dial = sniffing
        .should_dial_override(&found)
        .then(|| Destination::Name(found.domain, asked.port()));
    (dial, route, Some(found.protocol), pairs)
}

/// One tunnel request from either front, already resolved to its lane: the Foxy lane grants after its tunnel opens.
fn serve_connect(
    client: Connection,
    out: &Outbound,
    asked: &Destination,
    front: Front,
    prefix: &[u8],
    tag: Option<&str>,
    facts: FlowFacts<'_>,
) {
    serve_connect_at(client, out, asked, front, prefix, tag, facts, 0);
}

#[allow(clippy::too_many_arguments, clippy::too_many_lines)]
fn serve_connect_at(
    mut client: Connection,
    out: &Outbound,
    asked: &Destination,
    front: Front,
    prefix: &[u8],
    tag: Option<&str>,
    facts: FlowFacts<'_>,
    depth: u8,
) {
    let tag = tag.map(str::to_owned).or_else(default_outbound_tag);
    let _outbound = OutboundTag::enter(tag.as_deref());
    let _source = SendThroughGuard::enter(SEND_THROUGH.with(std::cell::Cell::take));
    let _sockopts = DialSockoptsGuard::enter(DIAL_SOCKOPTS.with(|cell| cell.borrow_mut().take()));
    let _target = TargetStrategyGuard::enter(TARGET_STRATEGY.with(std::cell::Cell::take));
    if let Outbound::Loopback(loopback) = out {
        let plan = loopback
            .shared()
            .filter(|_| depth < MAX_LOOPBACK_DEPTH)
            .map(|shared| {
                RoutePlan::new(
                    shared,
                    Some(loopback.inbound_tag.clone()),
                    loopback.inbound_name.clone(),
                    loopback.source_known,
                )
                .without_dns()
            });
        let want_attrs = plan.as_ref().is_some_and(RoutePlan::wants_attrs);
        let (dial, route, protocol, pairs) = loopback_sniffed(loopback, asked, &client, want_attrs);
        let target = dial.as_ref().unwrap_or(asked);
        if let Some(plan) = plan {
            let attrs = (!pairs.is_empty()).then(|| crate::router::Attributes::from_pairs(&pairs));
            let owner = plan.process_owner(crate::router::Network::Tcp, Some(&client));
            let second = FlowFacts {
                protocol,
                user: facts.user,
                level: facts.level,
                attrs: attrs.as_ref(),
                process: owner.as_ref(),
                original: Some(asked),
                route: route.as_ref().filter(|_| dial.is_none()),
                ..FlowFacts::default()
            };
            let route = route.as_ref().unwrap_or(asked);
            let (lane, lane_tag) =
                plan.lane_with_protocol(route, crate::router::Network::Tcp, Some(&client), second);
            if !same_loopback(&lane, loopback) {
                return serve_connect_at(
                    client,
                    &lane,
                    target,
                    front,
                    prefix,
                    lane_tag.as_deref(),
                    facts,
                    depth + 1,
                );
            }
        }
        if let Some(dial) = &loopback.dial {
            return serve_connect_at(
                client,
                dial,
                target,
                front,
                prefix,
                tag.as_deref(),
                facts,
                depth + 1,
            );
        }
        return;
    }
    // The rules dropped this flow: the front has granted it, so the sink answers and ends it.
    if let Outbound::Api(api) = out {
        api.serve_routed(client);
        return;
    }
    if let Outbound::Block(answer) = out {
        crate::blackhole::serve(client, answer);
        return;
    }
    if let Outbound::WireGuard(wireguard) = out {
        wireguard.serve_tcp(client, asked, prefix);
        return;
    }
    if let Outbound::Masque(masque) = out {
        masque.serve_tcp(client, asked, prefix);
        return;
    }
    if let Outbound::Warp(warp) = out {
        warp.serve_tcp(client, asked, prefix);
        return;
    }
    if let Outbound::Foxy(foxy) = out {
        return serve_foxy_front(client, foxy, asked, front, prefix);
    }
    if let Outbound::Veepn(lane) = out {
        return serve_veepn_front(client, lane, asked, front, prefix);
    }
    if let Outbound::Freedom(freedom) = out {
        serve_connect_freedom(&client, freedom, asked, prefix);
        return;
    }
    if !prefix.is_empty() {
        // A protocol outbound handshakes over the client's own bytes, so a consumed head has nowhere to go.
        let _ = client.write_all(b"HTTP/1.1 405 Method Not Allowed\r\nConnection: close\r\n\r\n");
        return;
    }
    if let Outbound::Dns(dns) = out {
        return serve_dns_tcp(client, dns, asked);
    }
    if let Outbound::ReversePortal(portal) = out {
        return serve_reverse_tcp(&client, portal, asked);
    }
    if let Outbound::Metrics { address } = out {
        let Some(mut upstream) = dial_or_report(address) else {
            return;
        };
        if !prefix.is_empty() && upstream.write_all(prefix).is_err() {
            return;
        }
        relay_handoff(&client, &upstream);
        return;
    }
    // xray's outbound handler resolves a named target before the request, so `targetStrategy` decides which answer goes out.
    let targeted = TARGET_STRATEGY.with(std::cell::Cell::get);
    let resolved = targeted.map(|strategy| resolve_target(asked, strategy));
    let asked = match &resolved {
        Some(TargetPick::Address(address)) => address,
        Some(TargetPick::Refuse) => return,
        _ => asked,
    };
    if let Outbound::Vless(vless) = out {
        if matches!(vless.carrier, Carrier::Quic) {
            if vless.mux.tcp.is_some() && dial_vless_mux(&client, vless, asked) {
                return;
            }
            if vless.encryption.is_some() {
                dial_vless_quic_sealed(&client, vless, asked);
            } else {
                crate::quic::dial_pooled(&client, &vless_quic_dial(vless), asked);
            }
            return;
        }
        if matches!(vless.carrier, Carrier::Kcp(_)) && vless.mux.tcp.is_none() {
            if let Some(session) = kcp_dial_session(&vless.carrier, &vless.address, vless.port) {
                dial_vless_kcp(&client, &session, vless, asked);
            }
            return;
        }
        if matches!(vless.carrier, Carrier::Hysteria(_)) {
            if vless.mux.tcp.is_some() && dial_vless_mux(&client, vless, asked) {
                return;
            }
            if let Some(dial) = hysteria_dial_session(vless) {
                crate::hysteria::dial_vless(&client, &dial, &vless.id, asked);
            }
            return;
        }
        if let Carrier::Xdrive { .. } = &vless.carrier {
            if vless.mux.tcp.is_none() || !dial_vless_mux(&client, vless, asked) {
                dial_vless_xdrive(&client, vless, asked);
            }
            return;
        }
    }
    if let Outbound::Vmess(vmess) = out {
        if matches!(vmess.carrier, Carrier::Kcp(_)) {
            if let Some(session) = kcp_dial_session(&vmess.carrier, &vmess.address, vmess.port) {
                dial_vmess_kcp(&client, &session, vmess, asked);
            }
            return;
        }
        if let Carrier::Xdrive { .. } = &vmess.carrier {
            if vmess.mux.tcp.is_none() || !dial_vmess_mux(&client, vmess, asked) {
                dial_vmess_xdrive(&client, vmess, asked);
            }
            return;
        }
    }
    if let Outbound::Trojan(trojan) = out {
        if matches!(trojan.carrier, Carrier::Quic) {
            let header = trojan_header(&trojan.key, 1, asked);
            crate::quic::dial_pooled_with(&client, &trojan_quic_dial(trojan), &header, false);
            return;
        }
        if matches!(trojan.carrier, Carrier::Hysteria(_)) {
            if trojan.mux.tcp.is_some() && dial_trojan_mux(&client, trojan, asked) {
                return;
            }
            let header = trojan_header(&trojan.key, 1, asked);
            if let Some(dial) = trojan_hysteria_dial(trojan) {
                crate::hysteria::dial_header(&client, &dial, &header, 0);
            }
            return;
        }
        if matches!(trojan.carrier, Carrier::Kcp(_)) {
            if let Some(session) = kcp_dial_session(&trojan.carrier, &trojan.address, trojan.port) {
                dial_trojan_kcp(&client, &session, trojan, asked);
            }
            return;
        }
        if let Carrier::Xdrive { .. } = &trojan.carrier {
            if trojan.mux.tcp.is_none() || !dial_trojan_mux(&client, trojan, asked) {
                dial_trojan_xdrive(&client, trojan, asked);
            }
            return;
        }
    }
    if let Outbound::Shadowsocks(ss) = out {
        if matches!(ss.carrier, Carrier::Kcp(_)) {
            if let Some(session) = kcp_dial_session(&ss.carrier, &ss.address, ss.port) {
                dial_ss_kcp(&client, &session, ss, asked);
            }
            return;
        }
        if matches!(ss.carrier, Carrier::Hysteria(_)) {
            if ss.mux.tcp.is_none() || !dial_ss_mux(&client, ss, asked) {
                if let Some(dial) = ss_hysteria_dial(ss) {
                    dial_ss_hysteria(&client, &dial, ss, asked);
                }
            }
            return;
        }
        if let Carrier::Xdrive { .. } = &ss.carrier {
            if ss.mux.tcp.is_none() || !dial_ss_mux(&client, ss, asked) {
                dial_ss_xdrive(&client, ss, asked);
            }
            return;
        }
    }
    let Some(server) = out.edge() else { return };
    dial_socks_outbound(&client, out, &server, asked);
}

fn dial_socks_outbound(
    client: &Connection,
    out: &Outbound,
    server: &SocketAddr,
    target: &Destination,
) {
    let ladder = Ladder::global();
    match out {
        Outbound::Vless(vless) => {
            if vless.mux.tcp.is_none() || !dial_vless_mux(client, vless, target) {
                dial_vless(client, server, vless, Some(target), ladder);
            }
        }
        Outbound::Vmess(vmess) => {
            if vmess.mux.tcp.is_none() || !dial_vmess_mux(client, vmess, target) {
                dial_vmess(client, server, vmess, target, ladder);
            }
        }
        Outbound::Trojan(trojan) => {
            if trojan.mux.tcp.is_none() || !dial_trojan_mux(client, trojan, target) {
                dial_trojan(client, server, trojan, target, ladder);
            }
        }
        Outbound::Shadowsocks(shadowsocks) => {
            if shadowsocks.mux.tcp.is_none() || !dial_ss_mux(client, shadowsocks, target) {
                dial_shadowsocks(client, server, shadowsocks, target, ladder);
            }
        }
        Outbound::Hysteria(hy) => crate::hysteria_v1::dial(client, &hy.dial(), target),
        Outbound::Http(http) => {
            dial_http_outbound(client, server, http, target, ladder);
        }
        Outbound::Socks(socks) => {
            let destination = socks_destination(target);
            if socks.tls.is_none() {
                dial_socks_client(
                    client,
                    server,
                    &socks.credential,
                    socks.version,
                    &destination,
                );
            } else {
                dial_socks_tls_client(client, server, socks, &destination);
            }
        }
        Outbound::Psiphon(lane) => {
            let destination = socks_destination(target);
            let (version, credential) = lane.session(&destination);
            dial_socks_client(client, server, credential, version, &destination);
        }
        Outbound::Foxy(_)
        | Outbound::Veepn(_)
        | Outbound::Freedom(_)
        | Outbound::Route(_)
        | Outbound::Loopback(_)
        | Outbound::Block(_)
        | Outbound::Dns(_)
        | Outbound::ReversePortal(_)
        | Outbound::WireGuard(_)
        | Outbound::Masque(_)
        | Outbound::Warp(_)
        | Outbound::Metrics { .. }
        | Outbound::Api(_) => {}
    }
}

/// The SOCKS5 client: the greeting, the credential exchange, the `CONNECT` request, and
/// then the tunnel.
///
/// The destination keeps its shape on the wire: a name the caller asked for is a name in
/// the request, so the server resolves it and this tree's resolver never sees it.
fn socks_destination(target: &Destination) -> crate::socks::Destination<'_> {
    match target {
        Destination::Address(address) => match address.ip() {
            std::net::IpAddr::V4(octets) => {
                crate::socks::Destination::V4(octets.octets(), address.port())
            }
            std::net::IpAddr::V6(octets) => {
                crate::socks::Destination::V6(octets.octets(), address.port())
            }
        },
        Destination::Name(host, port) => crate::socks::Destination::Name(host.as_bytes(), *port),
    }
}

fn dial_socks_client(
    client: &Connection,
    server: &SocketAddr,
    credential: &crate::socks::Credential,
    version: crate::socks::Version,
    destination: &crate::socks::Destination<'_>,
) {
    let Some(upstream) = dial_or_report(server) else {
        return;
    };
    let read = upstream.read_timeout().ok().flatten();
    let _ = upstream.set_read_timeout(Some(budgets::SESSION_POLL));
    let _ = upstream.set_write_timeout(Some(budgets::handshake()));
    let Some(tunnel) = crate::socks::connect(upstream, credential, destination, version) else {
        return;
    };
    let _ = tunnel.set_read_timeout(read);
    let _ = tunnel.set_write_timeout(None);
    relay_handoff(client, &tunnel);
}

/// The SOCKS5 handshake inside a TLS session: the transport is dialled, the carrier is
/// connected inside the session when the config names one, and the SOCKS exchange runs
/// over that byte stream instead of the raw socket.
fn dial_socks_tls_client(
    client: &Connection,
    server: &SocketAddr,
    socks: &SocksOut,
    destination: &crate::socks::Destination<'_>,
) {
    use ferrox_core::vless_encryption::SplitIo as _;
    let Some(cfg) = socks.tls.as_ref() else {
        return;
    };
    if matches!(socks.carrier, Carrier::Kcp(_)) {
        let Some((conn, session)) =
            kcp_tls_session(&socks.carrier, &socks.address, socks.port, cfg)
        else {
            return;
        };
        let Some(tunnel) =
            crate::socks::connect(session, &socks.credential, destination, socks.version)
        else {
            conn.close();
            return;
        };
        relay_kcp_under(client, &conn, tunnel, &[], |_| true);
        return;
    }
    if matches!(socks.carrier, Carrier::Raw(_)) {
        let Some(session) = dial_tls_session(server, cfg, socks.carrier.tcp_mask()) else {
            return;
        };
        let Some((reader, writer, _)) = session.into_halves() else {
            return;
        };
        let Some(tunnel) = crate::socks::connect(
            CarrierStream { reader, writer },
            &socks.credential,
            destination,
            socks.version,
        ) else {
            return;
        };
        let Some((reader, writer)) = tunnel.split_io() else {
            return;
        };
        let sink = RelayWrite::new(Box::new(writer));
        relay_sink(reader, &sink, client, |_| {});
        return;
    }
    let Some(stream) = dial_tls_carried_stream(
        server,
        cfg,
        &socks.carrier,
        &socks.host,
        &socks.carrier_headers,
        socks.heartbeat,
    ) else {
        return;
    };
    let Some(tunnel) = crate::socks::connect(stream, &socks.credential, destination, socks.version)
    else {
        return;
    };
    let Some((reader, writer)) = tunnel.split_io() else {
        return;
    };
    let sink = RelayWrite::new(writer);
    relay_sink(reader, &sink, client, |_| {});
}

/// The split-tunnel list: targets this lane does not carry, which leave by the plain dial.
fn foxy_splits(ports: &[u16], suffixes: &[String], asked: &Destination) -> bool {
    if ports.contains(&asked.port()) {
        return true;
    }
    // A domain list decides names only: an address leaves by a port or not at all.
    let Destination::Name(host, _) = asked else {
        return false;
    };
    suffixes.iter().any(|suffix| {
        let suffix = suffix
            .strip_prefix("*.")
            .or_else(|| suffix.strip_prefix('.'))
            .unwrap_or(suffix)
            .trim_end_matches('.');
        !suffix.is_empty()
            && host.len() >= suffix.len()
            && (host.len() == suffix.len()
                || host.as_bytes()[host.len() - suffix.len() - 1] == b'.')
            && host[host.len() - suffix.len()..].eq_ignore_ascii_case(suffix)
    })
}

fn foxy_socks_reply(reply: u8) -> [u8; 10] {
    [5, reply, 0, 1, 0, 0, 0, 0, 0, 0]
}

/// Edges past the first a refusal may try: the reference's count, and the most a flow is worth waiting for.
const MAX_FOXY_ALTERNATES: usize = 3;

/// The renewal thread: one per lane on the clock the pass names, stopping once the account itself is refused.
fn start_renewal(account: std::sync::Arc<crate::foxy_account::Account>) {
    thread::spawn(move || {
        let mut attempt = 0u32;
        loop {
            thread::sleep(account.renews_in());
            let Err(denied) = account.renew() else {
                attempt = 0;
                // The plane re-states the allowance on every mint, so the line a status reads is the one the latest pass carries.
                if let Some(line) = account.current().allowance_line() {
                    eprintln!("foxy: allowance {line}");
                }
                continue;
            };
            // A refused token is the only end: a rate limit, a challenge or an unreachable plane is asked again on the plane's own pause, since the pass it stands over keeps expiring meanwhile.
            if denied.is_final() {
                eprintln!(
                    "foxy: the pass cannot be replaced ({denied}): restart the lane to sign in"
                );
                return;
            }
            let pause = crate::foxy_account::renewal_gap(&denied, attempt, account.pass_left());
            attempt = attempt.saturating_add(1);
            eprintln!(
                "foxy: the pass could not be replaced ({denied}), asking again in {}s",
                pause.as_secs()
            );
            thread::sleep(pause);
        }
    });
}

/// First bytes of each direction behind `FOXY_DEBUG`, so a tunnel that answers TLS with plaintext names itself, and with the moment they landed so a slow answer names the half it waited on.
fn debug_bytes(direction: &str, buf: &[u8], after: Option<Instant>) {
    if crate::foxy::debug_on() {
        let end = buf.len().min(32);
        eprintln!(
            "foxy-debug: {direction} first {end} B in {}ms: {:02x?}",
            trace_ms(after),
            &buf[..end]
        );
    }
}

/// How long a phase took, for a trace line: an untraced open hands this `None`, so a shipped lane makes no clock call for a number nobody reads.
fn trace_ms(at: Option<Instant>) -> u128 {
    at.map_or(0, |started| started.elapsed().as_millis())
}

/// Lane trace behind `FOXY_DEBUG`: edge, carrier and outcome per dial, so a stall names where it stopped. The outcome is a closure because the lane's own trace is off by default, and the text it carries was built per flow: an authority joined per dial and a message formatted per attempt, both for a line nobody reads.
fn debug_lane(
    edge: &ferrox_core::foxy::Candidate,
    carrier: crate::foxy::Carrier,
    what: impl FnOnce() -> String,
) {
    if crate::foxy::debug_on() {
        eprintln!("foxy-debug: {} {:?} {}", edge.authority(), carrier, what());
    }
}

/// The stamps of one granted open behind `FOXY_DEBUG`: the lane's own dial and the CONNECT that rode it, in the milliseconds each took.
fn debug_open(
    edge: &ferrox_core::foxy::Candidate,
    carrier: crate::foxy::Carrier,
    target: &str,
    lane: Option<Instant>,
    open: Option<Instant>,
) {
    debug_lane(edge, carrier, || {
        format!(
            "opened for {target} lane={}ms open={}ms",
            trace_ms(lane),
            trace_ms(open)
        )
    });
}

/// Relay totals behind `FOXY_DEBUG`: which direction ended, after how many bytes, after how many turns the lane could not park through, and on what error kind.
fn debug_relay(direction: &str, moved: u64, sleeps: u32, error: Option<std::io::ErrorKind>) {
    if crate::foxy::debug_on() {
        eprintln!(
            "foxy-debug: relay {direction} ended after {moved} B with {sleeps} unparked sleeps on {error:?}"
        );
    }
}

/// Which byte front a tunnel answers: the grant and refusal render per front, the tunnel loop does not.
#[derive(Debug, Clone, Copy)]
pub(crate) enum Front {
    Socks,
    Http,
    Probe,
}

impl Front {
    fn grant_line(self) -> &'static [u8] {
        const SOCKS_GRANTED: [u8; 10] = [5, 0, 0, 1, 0, 0, 0, 0, 0, 0]; // `foxy_socks_reply`'s code 0
        match self {
            Self::Socks => &SOCKS_GRANTED,
            Self::Http => b"HTTP/1.1 200 Connection established\r\n\r\n",
            Self::Probe => &[],
        }
    }
    fn direct_grant(self) -> Option<&'static [u8]> {
        match self {
            Self::Socks | Self::Probe => None,
            Self::Http => Some(self.grant_line()),
        }
    }
    fn refusal(self, code: u8) -> Vec<u8> {
        match self {
            Self::Socks => foxy_socks_reply(code).to_vec(),
            Self::Http => b"HTTP/1.1 502 Bad Gateway\r\nConnection: close\r\n\r\n".to_vec(),
            Self::Probe => Vec::new(),
        }
    }
}

/// An opened Foxy route: a tunnel that carries its own pooled stream, a direct dial, a refusal code, or nothing to say.
enum FoxyOpen {
    /// The lane carries the pool entry it owes, so the flow that ends it is the flow that pays the pool back.
    Tunnel(Box<crate::foxy::Tunnel>, ferrox_core::foxy::Candidate),
    Direct(SocketAddr),
    Refused(u8),
    Silent,
}

/// Whether a flow may dial yet: inside the curve it is refused locally, another attempt only extends the limit.
fn edge_limited(until: &AtomicU64, now: u64) -> bool {
    until.load(Ordering::Relaxed) > now
}

/// Records one limited attempt and returns the next allowed dial, climbing the curve instead of hammering.
fn note_limited(strikes: &AtomicU32, until: &AtomicU64, now: u64) -> u64 {
    let wait = ferrox_core::foxy::refusal_backoff(strikes.fetch_add(1, Ordering::Relaxed));
    let at = now.saturating_add(wait.as_secs());
    until.store(at, Ordering::Relaxed);
    at
}

/// A working tunnel clears the limit: the curve restarts instead of punishing later flows for an old limit.
fn clear_limited(strikes: &AtomicU32, until: &AtomicU64) {
    strikes.store(0, Ordering::Relaxed);
    until.store(0, Ordering::Relaxed);
}

/// Whether the exit probe names a real pin a disposable tunnel can answer: no probe, or `REC`, needs none.
fn exit_needs_probe(foxy: &FoxyOut) -> bool {
    foxy.exit_probe.is_some()
        && !foxy
            .country
            .eq_ignore_ascii_case(ferrox_core::foxy::catalog::RECOMMENDED)
}

/// Given each edge's probe answer in dial order — `None` carried no probe, `Some(true)` exits the pinned country, `Some(false)` exits elsewhere — the index to prefer, or `None` to keep the label order.
#[must_use]
fn pick_verified_edge(probes: &[Option<bool>]) -> Option<usize> {
    probes
        .iter()
        .position(|answer| matches!(answer, Some(true)))
}

/// Whether the answers read so far already fix the pick: once an edge honours the pin, a later probe cannot un-prefer it, so the walk is settled and every probe past here is dead work.
#[must_use]
fn probe_settled(probes: &[Option<bool>]) -> bool {
    pick_verified_edge(probes).is_some()
}

/// Whether any edge answered a probe at all: none did means this runner cannot dial the probe tunnel, so stop trying.
#[must_use]
fn probes_reachable(probes: &[Option<bool>]) -> bool {
    probes.iter().any(Option::is_some)
}

/// What a finished probe sweep concluded: the edge that honoured the pin, no probe reachable from here, or every reachable edge answering a different country than the pin.
#[derive(Debug, PartialEq, Eq)]
enum Sweep {
    Agreed(usize),
    Unreachable,
    Refuted,
}

/// The verdict of a sweep, in the order the caller acts on it: a pick wins, an unreachable probe set stops the probes, and a set that answered and agreed with none is itself the answer.
#[must_use]
fn sweep_verdict(probes: &[Option<bool>]) -> Sweep {
    if let Some(at) = pick_verified_edge(probes) {
        return Sweep::Agreed(at);
    }
    if probes_reachable(probes) {
        Sweep::Refuted
    } else {
        Sweep::Unreachable
    }
}

/// The exit country one edge really hands back: a disposable H3 tunnel to the probe authority, asked for the trace, then dropped, which is what gives its pooled stream back. It never rides a flow's own tunnel, so a per-target carrier is left intact; `None` means this runner could not carry or read the trace here. The probe is a probe, so its dial gets the probe budget rather than a named carrier's full handshake: a lane whose UDP is blackholed has to say so before the first flow's client gives up.
fn probe_edge_exit(
    foxy: &FoxyOut,
    edge: &ferrox_core::foxy::Candidate,
    authority: &str,
) -> Option<String> {
    let pass = foxy
        .account
        .as_ref()
        .map_or_else(|| foxy.pass.clone(), |account| account.current());
    let dial = crate::foxy::FoxyDial {
        host: edge.host.clone(),
        port: edge.port,
        address: foxy.edge_address,
        carrier: crate::foxy::Carrier::H3,
        upstream: foxy.upstream.clone(),
        roots: foxy.roots.clone(),
        pins: foxy.pins.clone(),
        pass,
    };
    let quic_dial = foxy_quic_dial(foxy, edge);
    let budget = budgets::carrier_probe();
    let quic = crate::quic::pooled_stream_within(&quic_dial, budget)?;
    // The lease goes into the open and comes back with the lane: whoever ends the flow hands the pool entry over, and a probe that ends early ends with it.
    let opened = crate::foxy::Tunnel::open_within(&dial, authority, quic, budget);
    match opened {
        Ok(mut tunnel) => {
            // The trace read carries the same budget as the dial: no head inside it is no answer, not a wait.
            let _ = tunnel.set_read_quantum(budget);
            let seen = foxy_exit_country(&mut tunnel, foxy);
            drop(tunnel);
            seen
        }
        Err(_) => None,
    }
}

/// The pinned-country edge that really exits in the pin, chosen once per lane over disposable probes and cached so every carrier rides it. The walk stops at the first edge that honours the pin, since a later probe cannot change that pick. Falls back to the label order when no edge agrees, records the truth when one cannot, and stops probing when none can be reached here.
fn verify_exit(foxy: &FoxyOut) {
    if !exit_needs_probe(foxy)
        || foxy.probe_unavailable.load(Ordering::Relaxed)
        || edge_limited(&foxy.exit_refuted_until, now_secs())
    {
        return;
    }
    if foxy.verified.lock().is_ok_and(|kept| kept.is_some()) {
        return;
    }
    let Some(probe) = foxy.exit_probe.as_deref() else {
        return;
    };
    let Some(host) = probe.split('/').next() else {
        return;
    };
    let authority = format!("{host}:80");
    let edges = ferrox_core::foxy::dial_order(
        &foxy.ladder,
        &foxy.country,
        foxy.stored.as_deref(),
        MAX_FOXY_ALTERNATES,
    );
    let pin = foxy.country.to_ascii_uppercase();
    let mut flags: Vec<Option<bool>> = Vec::with_capacity(edges.len());
    for edge in edges.iter() {
        let agreed = probe_edge_exit(foxy, edge, &authority).map(|seen| {
            let agrees = exit_agrees(&foxy.country, &seen);
            if !agrees {
                debug_lane(edge, crate::foxy::Carrier::H3, || {
                    format!("exit {seen} differs from pin {pin}")
                });
            }
            agrees
        });
        flags.push(agreed);
        if probe_settled(&flags) {
            break;
        }
    }
    match sweep_verdict(&flags) {
        Sweep::Agreed(at) => {
            if let Ok(mut kept) = foxy.verified.lock() {
                if let Some(edge) = edges.get(at) {
                    *kept = Some(std::sync::Arc::new(edge.clone()));
                }
            }
        }
        // The pin is not what this runner gets out; re-sweeping it per flow would only buy the same refusal again.
        Sweep::Refuted => foxy
            .exit_refuted_until
            .store(now_secs() + CARRIER_DEAD_SECS, Ordering::Relaxed),
        Sweep::Unreachable => foxy.probe_unavailable.store(true, Ordering::Relaxed),
    }
}

/// The pre-flight belongs to no client's clock: the sweep runs once per lane on its own thread while the flow that scheduled it dials the label order, and the flows after it ride whatever edge the probe confirmed. Every verdict it writes goes through an `Arc`, so the clone the thread holds is only a dial snapshot.
fn schedule_exit_probe(foxy: &FoxyOut) {
    if !exit_needs_probe(foxy)
        || foxy.probe_unavailable.load(Ordering::Relaxed)
        || edge_limited(&foxy.exit_refuted_until, now_secs())
        || foxy.verified.lock().is_ok_and(|kept| kept.is_some())
    {
        return;
    }
    if foxy.exit_probe_running.swap(true, Ordering::Relaxed) {
        return;
    }
    let owned = std::sync::Arc::new(foxy.clone());
    let running = std::sync::Arc::clone(&owned.exit_probe_running);
    let spawned = std::thread::Builder::new()
        .name("foxy-exit-probe".to_string())
        .spawn(move || {
            verify_exit(&owned);
            running.store(false, Ordering::Relaxed);
        });
    if spawned.is_err() {
        foxy.exit_probe_running.store(false, Ordering::Relaxed);
    }
}

/// Shared loop: first answer wins, a refused pass stops every carrier and edge; the grant belongs to the front.
fn foxy_open(foxy: &FoxyOut, asked: &Destination) -> FoxyOpen {
    if foxy
        .unauthenticated
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        return FoxyOpen::Refused(0x01);
    }
    if edge_limited(&foxy.limited_until, now_secs()) {
        return FoxyOpen::Refused(0x01);
    }
    if foxy_splits(&foxy.direct_ports, &foxy.direct_suffixes, asked) {
        let Some(target) = asked.socket() else {
            return FoxyOpen::Silent;
        };
        return FoxyOpen::Direct(target);
    }
    // The target is spelled once, into a buffer the flow owns: a flow that joined the name and the port into a fresh string per carrier paid a heap buffer for every carrier it tried.
    let mut target = String::new();
    asked.authority_into(&mut target);
    schedule_exit_probe(foxy);
    let preferred = foxy.preferred_edge();
    let mut last = None;
    let order = ferrox_core::foxy::dial_order(
        &foxy.ladder,
        &foxy.country,
        preferred.as_deref(),
        MAX_FOXY_ALTERNATES,
    );
    for edge in foxy.live_dials(&order) {
        let pass = foxy
            .account
            .as_ref()
            .map_or_else(|| foxy.pass.clone(), |account| account.current());
        for carrier in foxy.carrier.order() {
            // As on UDP: a silent carrier is left alone for the window, not probed per flow.
            if foxy.carrier_unanswered(edge, carrier) {
                continue;
            }
            let dial = crate::foxy::FoxyDial {
                host: edge.host.clone(),
                port: edge.port,
                address: foxy.edge_address,
                carrier,
                upstream: foxy.upstream.clone(),
                roots: foxy.roots.clone(),
                pins: foxy.pins.clone(),
                pass: pass.clone(),
            };
            // A named carrier gets the full budget; an `auto` walk is a probe and gets the probe's.
            let lane_at = crate::foxy::debug_on().then(Instant::now);
            let quic = match carrier {
                crate::foxy::Carrier::H3 => crate::quic::pooled_stream_within(
                    &foxy_quic_dial(foxy, edge),
                    if foxy.carrier == crate::foxy::Carrier::H3 {
                        crate::quic::HANDSHAKE_TIMEOUT
                    } else {
                        budgets::carrier_probe()
                    },
                ),
                _ => None,
            };
            let open_at = lane_at.map(|_| Instant::now());
            match crate::foxy::Tunnel::open(&dial, &target, quic) {
                Ok(tunnel) => {
                    debug_open(edge, carrier, &target, lane_at, open_at);
                    foxy.unauthenticated
                        .store(false, std::sync::atomic::Ordering::Relaxed);
                    clear_limited(&foxy.limited_strikes, &foxy.limited_until);
                    foxy.carrier_answered(edge, carrier);
                    return FoxyOpen::Tunnel(Box::new(tunnel), (*edge).clone());
                }
                Err(failure) => {
                    debug_lane(edge, carrier, || {
                        format!("{} lane={}ms", failure, trace_ms(lane_at))
                    });
                    // A refused pass is the pass, not the edge: all carriers answer it the same.
                    if let ferrox_core::foxy::Failure::Rejected(status) = failure {
                        if ferrox_core::foxy::pass_is_rejected(status) {
                            foxy.unauthenticated
                                .store(true, std::sync::atomic::Ordering::Relaxed);
                            break;
                        }
                        // Account-wide limit: one attempt per flow, the rest wait out the curve.
                        if status == 429 {
                            note_limited(&foxy.limited_strikes, &foxy.limited_until, now_secs());
                            break;
                        }
                    }
                    // A status is the edge speaking, so only a silent carrier is remembered as dead.
                    foxy.remember_unanswered(edge, carrier, failure);
                    last = Some(failure);
                    // A refused chain is the edge's own certificate, not the carrier's: HTTP/2 and HTTP/1.1 would answer a trust failure exactly as this one did.
                    if matches!(failure, ferrox_core::foxy::Failure::Untrusted) {
                        break;
                    }
                }
            }
        }
    }
    FoxyOpen::Refused(last.map_or(0x01, crate::foxy::refusal_reply))
}

/// The Foxy half of either front: CONNECT grants, plain HTTP forwards its head, a split target dials direct.
fn serve_foxy_front(
    mut client: Connection,
    foxy: &FoxyOut,
    asked: &Destination,
    front: Front,
    prefix: &[u8],
) {
    match foxy_open(foxy, asked) {
        FoxyOpen::Tunnel(tunnel, edge) => {
            let mut tunnel = *tunnel;
            if prefix.is_empty() && client.write_all(front.grant_line()).is_err() {
                return;
            }
            if !prefix.is_empty() && tunnel.write_all(prefix).is_err() {
                return;
            }
            // One lock serves both directions: the lane's read takes a grain so a writer never waits out the wait, and the idle leg parks on the edge socket outside the lock.
            let _ = tunnel.set_relay_quantum(budgets::relay_quantum());
            let tunnel = std::sync::Arc::new(std::sync::Mutex::new(tunnel));
            let started = Instant::now();
            relay_tunnel(&client, &tunnel);
            // Both legs are joined, so the lane is no longer shared: a clean h2 session goes back to the pool instead of paying a handshake on the next flow.
            if let Ok(lane) = std::sync::Arc::try_unwrap(tunnel) {
                if let Ok(lane) = lane.into_inner() {
                    lane.settle();
                }
            }
            foxy.note_edge_end(&edge, started.elapsed());
        }
        FoxyOpen::Direct(target) => {
            let Some(mut upstream) = dial_or_report(&target) else {
                return;
            };
            if prefix.is_empty() {
                if let Some(grant) = front.direct_grant() {
                    if client.write_all(grant).is_err() {
                        return;
                    }
                }
            }
            if !prefix.is_empty() && upstream.write_all(prefix).is_err() {
                return;
            }
            relay_handoff(&client, &upstream);
        }
        FoxyOpen::Refused(code) => {
            let _ = client.write_all(&front.refusal(code));
        }
        FoxyOpen::Silent => {}
    }
}

/// The `VeePN` half of either front: the plane names the upstream, the `Foxy` record lane opens it, and the grant waits for that open as it does for Foxy's.
fn serve_veepn_front(
    mut client: Connection,
    lane: &crate::veepn::VeepnOut,
    asked: &Destination,
    front: Front,
    prefix: &[u8],
) {
    let mut tunnel = match lane.open(&asked.authority()) {
        Ok(tunnel) => tunnel,
        Err(why) => {
            eprintln!("veepn: {}", why.why);
            let _ = client.write_all(&front.refusal(why.code));
            return;
        }
    };
    if prefix.is_empty() && client.write_all(front.grant_line()).is_err() {
        return;
    }
    if !prefix.is_empty() && tunnel.write_all(prefix).is_err() {
        return;
    }
    // The same one lock serves both directions as a Foxy flow's, so it gets the same arm: a grain for the read, the wait outside the lock.
    let _ = tunnel.set_relay_quantum(budgets::relay_quantum());
    relay_tunnel(&client, &std::sync::Arc::new(std::sync::Mutex::new(tunnel)));
}

const HTTP_HEAD_LIMIT: usize = 8192;
/// An HTTP proxy request: a tunnel to open, or a head to forward to a raw uplink.
enum ProxyRequest {
    Connect(Destination),
    Forward(Destination, Vec<u8>),
}

/// CONNECT tunnels; absolute- and origin-form forward the head with its line rewritten to origin-form.
fn http_proxy_request(mut head: Vec<u8>) -> Option<ProxyRequest> {
    let line_end = ferrox_core::foxy::octet_in(&head, 0, b'\n');
    let raw = &head[..line_end.unwrap_or(head.len())];
    let line = raw.strip_suffix(b"\r").unwrap_or(raw);
    let mut parts = line.split(|byte| *byte == b' ');
    let method = parts.next()?;
    let target = parts.next()?;
    let sent_version = parts.next();
    if method.eq_ignore_ascii_case(b"CONNECT") {
        return authority_target(connect_authority(target)).map(ProxyRequest::Connect);
    }
    if method.eq_ignore_ascii_case(b"OPTIONS")
        || method.eq_ignore_ascii_case(b"TRACE")
        || target.is_empty()
    {
        return None;
    }
    if let Some(rest) = target.strip_prefix(b"http://") {
        let (authority, path) = match ferrox_core::foxy::octet_in(rest, 0, b'/') {
            Some(at) => (&rest[..at], &rest[at..]),
            None => (rest, b"/".as_slice()),
        };
        let asked = authority_target(authority)?;
        // The pieces' places in the head, for a rewrite that moves the head's own bytes.
        let base = head.as_ptr() as usize;
        let place = |piece: &[u8]| {
            let at = piece.as_ptr() as usize - base;
            (at, at + piece.len())
        };
        let line = RequestLine {
            method: place(method),
            path: if path == b"/" {
                None
            } else {
                Some(place(path))
            },
            version: sent_version.map(place),
        };
        origin_head(&mut head, line_end, &line);
        return Some(ProxyRequest::Forward(asked, head));
    }
    if target.starts_with(b"/") {
        let host = header_value(&head, "host")?;
        let asked = authority_target(host.as_bytes())?;
        // The line is already origin-form as it landed, so the head needs no rewrite to reach the uplink.
        let untouched = line_end.is_some()
            && raw.len() == line.len() + 1
            && sent_version.is_some()
            && parts.next().is_none();
        if !untouched {
            let base = head.as_ptr() as usize;
            let place = |piece: &[u8]| {
                let at = piece.as_ptr() as usize - base;
                (at, at + piece.len())
            };
            let line = RequestLine {
                method: place(method),
                path: Some(place(target)),
                version: sent_version.map(place),
            };
            origin_head(&mut head, line_end, &line);
        }
        return Some(ProxyRequest::Forward(asked, head));
    }
    None
}

/// A CONNECT target is the authority form; Go's transport also sends the
/// absolute form (`Connect http://host:port/`) when the method is CONNECT and
/// the destination is plain.
fn connect_authority(target: &[u8]) -> &[u8] {
    let rest = [b"http://".as_slice(), b"https://".as_slice()]
        .into_iter()
        .find_map(|scheme| target.strip_prefix(scheme))
        .unwrap_or(target);
    match ferrox_core::foxy::octet_in(rest, 0, b'/') {
        Some(at) => &rest[..at],
        None => rest,
    }
}

/// The request line's three pieces, as ranges inside the head they were read from: the
/// rewrite moves the head's own bytes, so the pieces are named by where they are rather
/// than by what they point at.
struct RequestLine {
    method: (usize, usize),
    /// The path inside the head, or the root path when the absolute form carried none.
    path: Option<(usize, usize)>,
    version: Option<(usize, usize)>,
}

/// Rewrites the request line to origin-form, keeping every header byte as sent. The
/// rewrite happens inside the head's own buffer: the headers shift left to where the
/// shorter line ends, so they are not copied at all.
fn origin_head(head: &mut Vec<u8>, line_end: Option<usize>, line: &RequestLine) {
    const VERSION: &[u8] = b"HTTP/1.1";
    const ROOT: &[u8] = b"/";
    let at = line_end.map_or(0, |at| at + 1);
    let tail = head.len() - at;
    let (m0, m1) = line.method;
    let (p0, p1) = line.path.unwrap_or((0, ROOT.len()));
    let version = line.version.unwrap_or((0, VERSION.len()));
    let want = (m1 - m0) + 1 + (p1 - p0) + 1 + (version.1 - version.0) + 2;
    if want > at {
        head.resize(head.len() + (want - at), 0);
    }
    let mut at_new = 0;
    head.copy_within(m0..m1, at_new);
    at_new += m1 - m0;
    head[at_new] = b' ';
    at_new += 1;
    if line.path.is_some() {
        head.copy_within(p0..p1, at_new);
        at_new += p1 - p0;
    } else {
        head[at_new..at_new + ROOT.len()].copy_from_slice(ROOT);
        at_new += ROOT.len();
    }
    head[at_new] = b' ';
    at_new += 1;
    if line.version.is_some() {
        head.copy_within(version.0..version.1, at_new);
        at_new += version.1 - version.0;
    } else {
        head[at_new..at_new + VERSION.len()].copy_from_slice(VERSION);
        at_new += VERSION.len();
    }
    head[at_new..at_new + 2].copy_from_slice(b"\r\n");
    // The headers move to where the new line ends, over the old line's own bytes.
    head.copy_within(at..at + tail, want);
    head.truncate(want + tail);
}

/// An authority as a target: a literal address stays one, a name rides the tunnel untouched, no port means 80.
fn authority_target(authority: &[u8]) -> Option<Destination> {
    let authority = std::str::from_utf8(authority).ok()?;
    if let Ok(address) = authority.parse::<SocketAddr>() {
        return Some(Destination::Address(address));
    }
    if let Ok(ip) = authority.parse::<std::net::IpAddr>() {
        return Some(Destination::Address(SocketAddr::new(ip, 80)));
    }
    let (host, port) = match authority.rsplit_once(':') {
        Some((host, port)) => (host, port.parse::<u16>().ok()?),
        None => (authority, 80),
    };
    // A name has no longer than a length byte to be carried by, and a truncated destination is a wrong one.
    if host.is_empty() || host.len() > ferrox_core::addr::MAX_DOMAIN {
        return None;
    }
    Some(Destination::Name(host.to_owned(), port))
}

/// xray's answer to an HTTP front that asks for a credential and was not handed an accepted one.
const HTTP_AUTH_REQUIRED: &[u8] =
    b"HTTP/1.1 407 Proxy Authentication Required\r\nProxy-Authenticate: Basic realm=\"proxy\"\r\n\r\n";

/// Whether the head carries an account this front accepts, decoded as xray decodes it: `Basic `, standard base64, the first colon.
fn http_credential_account<'a>(
    head: &[u8],
    accounts: &'a SocksAccounts,
) -> Option<&'a SocksAccount> {
    use base64::Engine as _;
    let value = header_value(head, "proxy-authorization")?;
    let encoded = value.strip_prefix("Basic ")?;
    let decoded = base64::engine::general_purpose::STANDARD
        .decode(encoded)
        .ok()?;
    let colon = decoded.iter().position(|byte| *byte == b':')?;
    accounts.account(&decoded[..colon], &decoded[colon + 1..])
}

/// The octets of the next `\r\n` line end, from a line's first octet: the first `\n` that a `\r` precedes, which is the two-octet window a walk would have matched, found one octet at a time.
fn crlf_in(head: &[u8], mut at: usize) -> Option<usize> {
    loop {
        let hit = ferrox_core::foxy::octet_in(head, at, b'\n')?;
        if hit > at && head[hit - 1] == b'\r' {
            return Some(hit - 1 - at);
        }
        at = hit + 1;
    }
}

/// Whether a header name is an HTTP token, which is what Go's header writer accepts and re-serializes.
fn header_name_is_token(name: &[u8]) -> bool {
    !name.is_empty()
        && name.iter().all(|byte| {
            byte.is_ascii_alphanumeric()
                || matches!(
                    byte,
                    b'!' | b'#'
                        | b'$'
                        | b'%'
                        | b'&'
                        | b'\''
                        | b'*'
                        | b'+'
                        | b'-'
                        | b'.'
                        | b'^'
                        | b'_'
                        | b'`'
                        | b'|'
                        | b'~'
                )
        })
}

/// Whether a response head is an interim `1xx`, which is answered and then followed by the final head.
fn http_head_is_interim(head: &[u8]) -> bool {
    let line = head.split(|byte| *byte == b'\n').next().unwrap_or(&[]);
    let mut parts = line.split(|byte| *byte == b' ');
    let _version = parts.next();
    let code = parts.next().unwrap_or(&[]);
    code.len() == 3 && code[0] == b'1' && code != b"101" && code.iter().all(u8::is_ascii_digit)
}

/// Whether every header line's name is an HTTP token, so a head that needs no rewrite can be forwarded as it landed.
fn header_names_are_tokens(head: &[u8]) -> bool {
    let mut at = ferrox_core::foxy::octet_in(head, 0, b'\n').map_or(head.len(), |at| at + 1);
    while at < head.len() {
        let Some(end) = ferrox_core::foxy::octet_in(head, at, b'\n') else {
            return true;
        };
        let raw = &head[at..end];
        let line = raw.strip_suffix(b"\r").unwrap_or(raw);
        if line.is_empty() {
            return true;
        }
        if line
            .first()
            .is_some_and(|byte| *byte == b' ' || *byte == b'\t')
        {
            at = end + 1;
            continue;
        }
        let valid = line
            .iter()
            .position(|byte| *byte == b':')
            .is_some_and(|colon| header_name_is_token(&line[..colon]));
        if !valid {
            return false;
        }
        at = end + 1;
    }
    true
}

/// Removes every header line whose name is not an HTTP token, in place: a name the origin would
/// frame differently from the bytes this side relays is a request-smuggling desync, not a header.
fn drop_invalid_header_names(head: &mut Vec<u8>) {
    let mut at = ferrox_core::foxy::octet_in(head, 0, b'\n').map_or(head.len(), |at| at + 1);
    let mut dropped = false;
    while at < head.len() {
        let Some(end) = ferrox_core::foxy::octet_in(head, at, b'\n') else {
            return;
        };
        let raw = &head[at..end];
        let line = raw.strip_suffix(b"\r").unwrap_or(raw);
        if line.is_empty() {
            return;
        }
        if line
            .first()
            .is_some_and(|byte| *byte == b' ' || *byte == b'\t')
        {
            if !dropped {
                at = end + 1;
                continue;
            }
            head.copy_within(end + 1.., at);
            head.truncate(head.len() - (end + 1 - at));
            continue;
        }
        let valid = line
            .iter()
            .position(|byte| *byte == b':')
            .is_some_and(|colon| header_name_is_token(&line[..colon]));
        if valid {
            dropped = false;
            at = end + 1;
            continue;
        }
        dropped = true;
        head.copy_within(end + 1.., at);
        head.truncate(head.len() - (end + 1 - at));
    }
}

/// Removes every line naming a header, in place; the credential is the proxy's, not the origin's.
fn drop_header(head: &mut Vec<u8>, name: &str) {
    let mut at = ferrox_core::foxy::octet_in(head, 0, b'\n').map_or(head.len(), |at| at + 1);
    while at < head.len() {
        let Some(end) = crlf_in(head, at) else {
            return;
        };
        let named = {
            let line = &head[at..at + end];
            line.len() > name.len()
                && line[name.len()] == b':'
                && line[..name.len()].eq_ignore_ascii_case(name.as_bytes())
        };
        if named {
            head.copy_within(at + end + 2.., at);
            head.truncate(head.len() - end - 2);
            continue;
        }
        at += end + 2;
    }
}

/// The method and path the reference's HTTP inbound reads off the request line it was sent, before
/// this front rewrites the line to origin-form: the method uppercased, the path percent-decoded and
/// without its query, and an absolute target with no path naming the empty one the reference parses.
fn request_line_attributes(head: &[u8]) -> Option<(String, String)> {
    let end = ferrox_core::foxy::octet_in(head, 0, b'\n')?;
    let line = head[..end].strip_suffix(b"\r").unwrap_or(&head[..end]);
    let mut parts = line.split(|byte| *byte == b' ');
    let method = std::str::from_utf8(parts.next()?).ok()?;
    let target = std::str::from_utf8(parts.next()?).ok()?;
    let path = if target.starts_with('/') {
        target
    } else {
        let rest = target.split_once("://").map_or(target, |(_, rest)| rest);
        rest.find('/').map_or("", |slash| &rest[slash..])
    };
    let path = path.split('?').next().unwrap_or("");
    Some((method.to_ascii_uppercase(), decoded_path(path).into_owned()))
}

/// The path the reference's `URL.Path` holds: every `%XX` decoded. An escape that is not two hex
/// digits stays as it was sent, where the reference's parse would have refused the request.
fn decoded_path(path: &str) -> std::borrow::Cow<'_, str> {
    let bytes = path.as_bytes();
    if !bytes.contains(&b'%') {
        return std::borrow::Cow::Borrowed(path);
    }
    let hex = |byte: u8| (byte as char).to_digit(16).map(|digit| digit as u8);
    let mut out = Vec::with_capacity(bytes.len());
    let mut at = 0;
    while at < bytes.len() {
        let escape = (bytes[at] == b'%' && at + 2 < bytes.len())
            .then(|| (hex(bytes[at + 1]), hex(bytes[at + 2])));
        if let Some((Some(high), Some(low))) = escape {
            out.push(high << 4 | low);
            at += 3;
        } else {
            out.push(bytes[at]);
            at += 1;
        }
    }
    std::borrow::Cow::Owned(String::from_utf8_lossy(&out).into_owned())
}

/// Every header the reference's hop-by-hop removal leaves, by the name it was sent with, plus the
/// empty `User-Agent` it inserts when the client sent none; `host` is promoted off the header map.
fn forward_headers<'a>(head: &'a [u8], attrs: &mut crate::router::Attributes<'a>) {
    let Some(line_end) = ferrox_core::foxy::octet_in(head, 0, b'\n') else {
        return;
    };
    let named = connection_named(head, line_end + 1);
    let mut user_agent = false;
    let mut at = line_end + 1;
    while at < head.len() {
        let Some(end) = ferrox_core::foxy::octet_in(head, at, b'\n') else {
            break;
        };
        let raw = &head[at..end];
        let line = raw.strip_suffix(b"\r").unwrap_or(raw);
        if line.is_empty() {
            break;
        }
        if let Some(colon) = ferrox_core::foxy::octet_in(line, 0, b':') {
            let name = &line[..colon];
            if !hop_by_hop(name, named) && !name.eq_ignore_ascii_case(b"host") {
                if let Ok(name) = std::str::from_utf8(name) {
                    let user_agent_header = name.eq_ignore_ascii_case("user-agent");
                    user_agent |= user_agent_header;
                    let value = &line[colon + 1..];
                    match std::str::from_utf8(value) {
                        Ok(value) => attrs.push(name, std::borrow::Cow::Borrowed(value.trim())),
                        Err(_) if user_agent_header => attrs.push(
                            name,
                            std::borrow::Cow::Owned(
                                String::from_utf8_lossy(value).trim().to_owned(),
                            ),
                        ),
                        Err(_) => {}
                    }
                }
            }
        }
        at = end + 1;
    }
    if !user_agent {
        attrs.push("user-agent", std::borrow::Cow::Borrowed(""));
    }
}

/// The first `Connection` header's value, whose comma-separated names the reference also drops.
fn connection_named(head: &[u8], from: usize) -> &[u8] {
    let mut at = from;
    while at < head.len() {
        let Some(end) = ferrox_core::foxy::octet_in(head, at, b'\n') else {
            break;
        };
        let raw = &head[at..end];
        let line = raw.strip_suffix(b"\r").unwrap_or(raw);
        if line.is_empty() {
            break;
        }
        if let Some(colon) = ferrox_core::foxy::octet_in(line, 0, b':') {
            if line[..colon].eq_ignore_ascii_case(b"connection") {
                return trim_bytes(&line[colon + 1..]);
            }
        }
        at = end + 1;
    }
    b""
}

fn hop_by_hop(name: &[u8], named: &[u8]) -> bool {
    const FIXED: [&[u8]; 8] = [
        b"connection",
        b"proxy-connection",
        b"proxy-authenticate",
        b"proxy-authorization",
        b"te",
        b"trailers",
        b"transfer-encoding",
        b"upgrade",
    ];
    FIXED.iter().any(|fixed| name.eq_ignore_ascii_case(fixed))
        || named
            .split(|byte| *byte == b',')
            .any(|piece| trim_bytes(piece).eq_ignore_ascii_case(name))
}

fn trim_bytes(mut bytes: &[u8]) -> &[u8] {
    while let [first, rest @ ..] = bytes {
        if first.is_ascii_whitespace() {
            bytes = rest;
        } else {
            break;
        }
    }
    while let [rest @ .., last] = bytes {
        if last.is_ascii_whitespace() {
            bytes = rest;
        } else {
            break;
        }
    }
    bytes
}

/// The `http` front: CONNECT tunnels like SOCKS, plain HTTP forwards its head, unparsable input closes quietly.
#[allow(clippy::too_many_lines)]
fn serve_http(mut client: Connection, out: &Outbound, accounts: &SocksAccounts) {
    let Some(mut head) = read_http_head(&mut client, HTTP_HEAD_LIMIT, budgets::head_arrival())
    else {
        return;
    };
    let account = if accounts.names_accounts() {
        let Some(account) = http_credential_account(&head, accounts) else {
            crate::accesslog::record(
                client.peer_addr().ok(),
                false,
                &"unknown",
                None,
                "rejected",
                "",
            );
            let _ = client.write_all(HTTP_AUTH_REQUIRED);
            return;
        };
        Some(account.clone())
    } else {
        None
    };
    if let Some(account) = &account {
        client = client
            .with_meter(crate::stats::user(&account.email, account.level))
            .with_policy(Some(crate::policy::flow(account.level)));
    }
    let email = account
        .as_ref()
        .map_or("", |account| account.email.as_str());
    let user = (!email.is_empty()).then_some(email);
    let level = account.as_ref().map(|account| account.level);
    drop_header(&mut head, "proxy-authorization");
    let request_line = out
        .wants_attrs()
        .then(|| request_line_attributes(&head))
        .flatten();
    let Some(request) = http_proxy_request(head) else {
        return;
    };
    match request {
        ProxyRequest::Connect(asked) => {
            let destination = asked.authority();
            crate::accesslog::record(client.peer_addr().ok(), true, &destination, None, "", email);
            let first = match crate::sniff::current() {
                Some(sniffing) if sniffing.enabled() => None,
                _ => Some(out.resolved_lane_with_protocol(
                    &asked,
                    crate::router::Network::Tcp,
                    Some(&client),
                    FlowFacts {
                        source: None,
                        local: None,
                        user,
                        level,
                        ..FlowFacts::default()
                    },
                )),
            };
            if !matches!(
                first.as_ref().map_or(out, |(lane, _)| &**lane),
                Outbound::Foxy(_) | Outbound::Veepn(_)
            ) && client.write_all(Front::Http.grant_line()).is_err()
            {
                return;
            }
            let (dial, out, tag) = match first {
                Some((lane, tag)) => (None, lane, tag),
                None => sniff_lane(out, &asked, &client, user, level),
            };
            let asked = dial.as_ref().unwrap_or(&asked);
            serve_connect(
                client,
                &out,
                asked,
                Front::Http,
                &[],
                tag.as_deref(),
                FlowFacts {
                    source: None,
                    local: None,
                    user,
                    level,
                    ..FlowFacts::default()
                },
            );
        }
        ProxyRequest::Forward(asked, origin) => {
            let destination = asked.authority();
            crate::accesslog::record(client.peer_addr().ok(), true, &destination, None, "", email);
            let attrs = request_line.map(|(method, path)| {
                let mut attrs = crate::router::Attributes::new();
                attrs.push(":method", std::borrow::Cow::Owned(method));
                attrs.push(":path", std::borrow::Cow::Owned(path));
                forward_headers(&origin, &mut attrs);
                attrs
            });
            let filtered = (!header_names_are_tokens(&origin)).then(|| {
                let mut copy = origin.clone();
                drop_invalid_header_names(&mut copy);
                copy
            });
            let prefix = filtered.as_deref().unwrap_or(&origin);
            let facts = FlowFacts {
                source: None,
                local: None,
                protocol: Some("http/1.1"),
                user,
                level,
                attrs: attrs.as_ref(),
                ..FlowFacts::default()
            };
            let (out, tag) = out.resolved_lane_with_protocol(
                &asked,
                crate::router::Network::Tcp,
                Some(&client),
                facts,
            );
            serve_connect(
                client,
                &out,
                &asked,
                Front::Http,
                prefix,
                tag.as_deref(),
                facts,
            );
        }
    }
}

/// The `mixed` front answers the same two shapes as the `socks` front on one listener.
fn serve_mixed(client: Connection, out: &Outbound, accounts: &SocksAccounts) {
    serve_socks(client, out, accounts);
}

fn now_secs() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |since| since.as_secs())
}

/// Whether an observed exit honours the pin: the recommended location accepts any, a pinned country accepts only its own code.
#[must_use]
fn exit_agrees(pin: &str, seen: &str) -> bool {
    pin.eq_ignore_ascii_case(ferrox_core::foxy::catalog::RECOMMENDED)
        || seen == pin.to_ascii_uppercase()
}

/// Whether the trace grew a blank line, walking the octets since the last ask rather than the whole buffer.
fn grew_blank_line(head: &[u8], scanned: &mut usize) -> bool {
    let from = head.len().min(*scanned).saturating_sub(1);
    *scanned = head.len();
    head[from..].windows(2).any(|pair| pair == b"\n\n")
}

/// Asks a tunnel where it really exits: one plaintext trace GET, then the `loc` off the reply. `None` when no probe is configured or the trace did not answer — the caller reads that as "no verdict," never as agreement.
fn foxy_exit_country<T: Read + Write>(tunnel: &mut T, foxy: &FoxyOut) -> Option<String> {
    let probe = foxy.exit_probe.as_deref()?;
    let (host, path) = probe.split_once('/')?;
    let request = format!("GET /{path} HTTP/1.1\r\nHost: {host}\r\nConnection: close\r\n\r\n");
    if tunnel.write_all(request.as_bytes()).is_err() {
        return None;
    }
    let mut head = Vec::with_capacity(1024);
    let mut chunk = [0u8; 512];
    let mut scanned = 0usize;
    loop {
        match tunnel.read(&mut chunk) {
            Ok(0) | Err(_) => break,
            Ok(read) => {
                head.extend_from_slice(&chunk[..read]);
                if grew_blank_line(&head, &mut scanned) || head.len() >= 4096 {
                    break;
                }
            }
        }
    }
    crate::foxy::exit_country(&head)
}

/// The relay a datagram flow rides: a loopback SOCKS5 association whose server half
/// runs `serve` and whose client half is the tree's own SOCKS5 UDP client.
///
/// The association is the protocol's own: the greeting, the method, the `UDP
/// ASSOCIATE` request and the reply that names the relay. The control leg comes back
/// with it and is held for the flow's life: dropping it ends the association, and the
/// lane stops relaying.
pub(crate) fn udp_association(
    serve: impl FnOnce(Connection) + Send + 'static,
) -> Option<crate::socks::Association<Connection>> {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").ok()?;
    let pair = listener.local_addr().ok()?;
    let client = std::net::TcpStream::connect(pair).ok()?;
    let (server, _) = listener.accept().ok()?;
    drop(listener);
    thread::spawn(move || serve(Connection::from(server)));
    crate::socks::associate(
        Connection::from(client),
        &crate::socks::Credential::default(),
    )
}

/// A leg on a SOCKS5 UDP relay: the socket the frames go through.
///
/// The leg's own source address is what routes the reply — the relay answers the
/// address the request came from — so one leg per client keeps the answers apart.
pub(crate) fn relay_leg(relay: SocketAddr) -> std::io::Result<UdpSocket> {
    let leg = UdpSocket::bind(SocketAddr::new(relay.ip(), 0))?;
    leg.connect(relay)?;
    leg.set_read_timeout(Some(budgets::udp_idle()))?;
    Ok(leg)
}

/// One association per source; the bound keeps distinct sources from pinning threads and sockets for the door's life.
const MAX_DOKODEMO_LEGS: usize = 1024;

/// The dokodemo UDP door: a datagram a client sends goes to the target the config
/// names, and the answer comes back to the client that sent it.
///
/// The door rides the outbound's own UDP lane over a loopback SOCKS5 association, the
/// same relay the `tun` front rides: the lane sees a datagram with a destination and
/// never learns that a door sent it.
///
/// The socket is the one the front bound, so the port is held from the moment the
/// inbound is armed, and a datagram that arrives before the door reads it waits in the
/// kernel rather than in a refusal.
fn dokodemo_udp_door(socket: &UdpSocket, dest: &Destination, out: &Outbound) {
    let Some(target) = dest.socket() else {
        eprintln!("dokodemo-door udp: rewrite target unusable, refused");
        return;
    };
    // One association per client: the upstream answers the source the request came from, so a shared association cannot route two clients' replies.
    let mut legs: HashMap<SocketAddr, (UdpSocket, Connection, Arc<AtomicBool>)> = HashMap::new();
    let mut buf = udp_buffer();
    // The door's frame is the door's: the address it rewrites to is the same for every datagram.
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    let _ = socket.set_read_timeout(Some(budgets::udp_idle()));
    loop {
        let (n, src) = match socket.recv_from(&mut buf) {
            Ok(read) => read,
            Err(error) if is_timeout(&error) => {
                legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
                continue;
            }
            Err(error) if is_udp_gone(&error) => {
                thread::sleep(UDP_POLL);
                legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
                continue;
            }
            Err(_) => return,
        };
        if n == 0 {
            continue;
        }
        if legs
            .get(&src)
            .is_some_and(|(_, _, alive)| !alive.load(Ordering::Relaxed))
        {
            legs.remove(&src);
        }
        if !legs.contains_key(&src) && legs.len() >= MAX_DOKODEMO_LEGS {
            legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
            if legs.len() >= MAX_DOKODEMO_LEGS {
                continue;
            }
        }
        let leg = match legs.entry(src) {
            std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
            std::collections::hash_map::Entry::Vacant(vacant) => {
                let outbound = out.clone();
                let Some(association) =
                    udp_association(move |conn| serve_socks(conn, &outbound, &no_accounts()))
                else {
                    eprintln!("dokodemo-door udp: the outbound refused the association");
                    continue;
                };
                let Ok(leg) = relay_leg(association.relay) else {
                    continue;
                };
                let Ok(writer) = socket.try_clone() else {
                    continue;
                };
                let Ok(reader) = leg.try_clone() else {
                    continue;
                };
                let alive = Arc::new(AtomicBool::new(true));
                let reader_alive = alive.clone();
                thread::spawn(move || {
                    let mut back = udp_buffer();
                    while let Ok(read) = reader.recv(&mut back) {
                        let Some((_source, payload)) = parse_socks_udp(&back[..read]) else {
                            continue;
                        };
                        if writer.send_to(payload, src).is_err() {
                            break;
                        }
                    }
                    reader_alive.store(false, Ordering::Relaxed);
                });
                vacant.insert((leg, association.control, alive))
            }
        };
        let out = socks_udp_frame(&mut frame, &target, &buf[..n]);
        let _ = leg.0.send(out);
    }
}

/// The transparent dokodemo UDP door: every datagram carries its own original destination,
/// and the answer must leave from that destination or the client drops it.
fn dokodemo_transparent_udp_door(socket: &UdpSocket, out: &Outbound, listen: SocketAddr) {
    type Flow = (SocketAddr, SocketAddr);
    let mut legs: HashMap<Flow, (UdpSocket, Connection, Arc<AtomicBool>)> = HashMap::new();
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    let _ = socket.set_read_timeout(Some(budgets::udp_idle()));
    loop {
        let (n, client, original) = match crate::transparent::receive_original(socket, &mut buf) {
            Ok(read) => read,
            Err(error) if is_timeout(&error) => {
                legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
                continue;
            }
            Err(error) if is_udp_gone(&error) => {
                thread::sleep(UDP_POLL);
                legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
                continue;
            }
            Err(error) if error.kind() == std::io::ErrorKind::InvalidData => continue,
            Err(_) => return,
        };
        if n == 0 {
            continue;
        }
        if dokodemo_loopback(&Destination::Address(original), listen) {
            continue;
        }
        let key = (client, original);
        if legs
            .get(&key)
            .is_some_and(|(_, _, alive)| !alive.load(Ordering::Relaxed))
        {
            legs.remove(&key);
        }
        if !legs.contains_key(&key) && legs.len() >= MAX_DOKODEMO_LEGS {
            legs.retain(|_, (_, _, alive)| alive.load(Ordering::Relaxed));
            if legs.len() >= MAX_DOKODEMO_LEGS {
                continue;
            }
        }
        let leg = match legs.entry(key) {
            std::collections::hash_map::Entry::Occupied(entry) => entry.into_mut(),
            std::collections::hash_map::Entry::Vacant(vacant) => {
                let outbound = out.clone();
                let Some(association) =
                    udp_association(move |conn| serve_socks(conn, &outbound, &no_accounts()))
                else {
                    eprintln!("dokodemo-door udp: the outbound refused the association");
                    continue;
                };
                let Ok(leg) = relay_leg(association.relay) else {
                    continue;
                };
                let Ok(writer) = crate::transparent::reply_socket(original) else {
                    continue;
                };
                let Ok(reader) = leg.try_clone() else {
                    continue;
                };
                let alive = Arc::new(AtomicBool::new(true));
                let reader_alive = alive.clone();
                thread::spawn(move || {
                    let mut back = udp_buffer();
                    while let Ok(read) = reader.recv(&mut back) {
                        let Some((_source, payload)) = parse_socks_udp(&back[..read]) else {
                            continue;
                        };
                        if writer.send_to(payload, client).is_err() {
                            break;
                        }
                    }
                    reader_alive.store(false, Ordering::Relaxed);
                });
                vacant.insert((leg, association.control, alive))
            }
        };
        let out = socks_udp_frame(&mut frame, &original, &buf[..n]);
        let _ = leg.0.send(out);
    }
}

fn socks_udp_relay(client: &mut Connection) -> Option<UdpSocket> {
    let local_ip = client
        .local_addr()
        .map_or(std::net::IpAddr::V4([127, 0, 0, 1].into()), |addr| {
            addr.ip()
        });
    let relay = UdpSocket::bind(SocketAddr::new(local_ip, 0)).ok()?;
    let relay_addr = relay.local_addr().ok()?;
    let mut reply = vec![5, 0, 0];
    push_socks_addr(&mut reply, &relay_addr);
    client.write_all(&reply).ok()?;
    relay.set_read_timeout(Some(budgets::udp_idle())).ok()?;
    Some(relay)
}

fn serve_socks_udp(client: Connection, out: &Outbound, user: Option<&str>, level: Option<u32>) {
    if let Outbound::Route(plan) = out {
        let association = plan.association();
        if matches!(association, Association::Split)
            || crate::sniff::current().is_some_and(|sniffing| sniffing.enabled())
        {
            return serve_socks_udp_split(client, plan, user, level);
        }
        if let Ok(target) = plan.udp_out(&association) {
            return serve_socks_udp_lane(client, &target);
        }
    }
    if !matches!(out, Outbound::Block(_))
        && crate::sniff::current().is_some_and(|sniffing| sniffing.enabled())
    {
        return serve_socks_udp_sniffed(client, out);
    }
    serve_socks_udp_lane(client, out);
}

/// One outbound that is not the routing plan still needs the sniffer's override: the lane reads
/// the datagram's own header, and this relay rewrites it before the outbound does.
fn serve_socks_udp_sniffed(mut client: Connection, out: &Outbound) {
    let Some(relay) = socks_udp_relay(&mut client) else {
        return;
    };
    let _ = relay.set_read_timeout(Some(UDP_POLL));
    let _ = client.set_read_timeout(Some(UDP_POLL));
    let local = relay
        .local_addr()
        .map_or(std::net::IpAddr::V4([127, 0, 0, 1].into()), |addr| {
            addr.ip()
        });
    let Some(lane) = spawn_udp_lane(out, local, None) else {
        return;
    };
    let lane_address = lane.address;
    let mut client_addr: Option<SocketAddr> = None;
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    let mut quiet = Instant::now();
    let mut checked = Instant::now();
    loop {
        if checked.elapsed() >= UDP_POLL {
            checked = Instant::now();
            if peer_left(&client) {
                break;
            }
        }
        let (n, src) = match relay.recv_from(&mut buf) {
            Ok(read) => {
                quiet = Instant::now();
                read
            }
            Err(error) => {
                if !is_timeout(&error) || quiet.elapsed() >= budgets::udp_idle() {
                    break;
                }
                continue;
            }
        };
        if src == lane_address {
            if let Some(client) = client_addr {
                let _ = relay.send_to(&buf[..n], client);
            }
            continue;
        }
        let Some((dest, payload)) = parse_socks_udp_dest(&buf[..n]) else {
            continue;
        };
        client_addr = Some(src);
        let mut dial = None;
        if let Some(sniffing) = crate::sniff::current().filter(|sniffing| sniffing.enabled()) {
            if let Some(found) = sniffing.inspect_udp(&dest, payload) {
                if sniffing.should_dial_override(&found) {
                    dial = Destination::Name(found.domain, dest.port()).socket();
                }
            }
        }
        let frame = match dial {
            Some(address) => socks_udp_frame(&mut frame, &address, payload),
            None => &buf[..n],
        };
        let _ = relay.send_to(frame, lane_address);
    }
    retire_udp_lanes(relay, HashMap::new(), Some(lane));
}

/// One lane for the whole association: every datagram reaches the same outbound.
fn serve_socks_udp_lane(mut client: Connection, out: &Outbound) {
    // A blackhole association is a refusal: a relay that drops every datagram reads as working.
    if matches!(out, Outbound::Block(_)) {
        let _ = client.write_all(&foxy_socks_reply(0x07));
        return;
    }
    let Some(relay) = socks_udp_relay(&mut client) else {
        return;
    };
    serve_udp_lane(&relay, out, Some(&client));
}

/// One outbound's datagram lane over a relay socket. The association is `None` when the lane is
/// itself an inner relay of a split association, whose control socket the splitter owns.
pub(crate) fn serve_udp_lane(relay: &UdpSocket, out: &Outbound, associate: Option<&Connection>) {
    let source = SEND_THROUGH.with(std::cell::Cell::take);
    let sockopts = DIAL_SOCKOPTS.with(|cell| cell.borrow_mut().take());
    serve_udp_lane_with(relay, out, associate, source, sockopts.as_ref());
}

#[allow(clippy::too_many_lines)]
fn serve_udp_lane_with(
    relay: &UdpSocket,
    out: &Outbound,
    associate: Option<&Connection>,
    source: Option<SendThrough>,
    sockopts: Option<&Arc<crate::sockopt::SocketOptions>>,
) {
    let _sockopts = DialSockoptsGuard::enter(sockopts.cloned());
    let sockopts = sockopts.map(Arc::as_ref);
    match out {
        // Loopback is TCP-only in the reference; a routed front tag has no datagram lane.
        Outbound::Loopback(loopback) => {
            if let Some(dial) = &loopback.dial {
                serve_udp_lane_with(relay, dial, associate, None, None);
            }
        }
        Outbound::Vless(vless) if matches!(vless.carrier, Carrier::Quic) => {
            serve_socks_udp_vless(relay, vless);
        }
        Outbound::Vless(vless)
            if matches!(vless.carrier, Carrier::Raw(_)) && vless.tls.is_none() =>
        {
            serve_socks_udp_vless(relay, vless);
        }
        Outbound::Vless(vless)
            if matches!(vless.carrier, Carrier::Kcp(_)) && vless.mux.tcp.is_some() =>
        {
            serve_socks_udp_vless(relay, vless);
        }
        Outbound::Vless(vless)
            if matches!(vless.carrier, Carrier::Hysteria(_))
                && vless.mux.udp_manager().is_some() =>
        {
            serve_socks_udp_vless(relay, vless);
        }
        Outbound::Vless(vless) if matches!(vless.carrier, Carrier::Hysteria(_)) => {
            // The datagram lane carries UDP flows the same way it carries TCP ones: one association per destination, ids never reused on the connection.
            if let Some(dial) = hysteria_dial_session(vless) {
                crate::hysteria::serve_udp(relay, &dial);
            }
        }
        Outbound::Vless(vless)
            if matches!(vless.carrier, Carrier::Xdrive { .. })
                && vless.mux.udp_manager().is_some() =>
        {
            serve_socks_udp_vless(relay, vless);
        }
        Outbound::Trojan(trojan)
            if matches!(trojan.carrier, Carrier::Hysteria(_))
                && trojan.mux.udp_manager().is_some() =>
        {
            serve_socks_udp_trojan(relay, trojan);
        }
        Outbound::Trojan(trojan) if matches!(trojan.carrier, Carrier::Hysteria(_)) => {
            if let Some(dial) = trojan_hysteria_dial(trojan) {
                crate::hysteria::serve_udp(relay, &dial);
            }
        }
        Outbound::Trojan(trojan)
            if matches!(trojan.carrier, Carrier::Xdrive { .. })
                && trojan.mux.udp_manager().is_some() =>
        {
            serve_socks_udp_trojan(relay, trojan);
        }
        Outbound::Trojan(trojan) if trojan_udp_carried(&trojan.carrier) => {
            serve_socks_udp_trojan(relay, trojan);
        }
        Outbound::Vmess(vmess) => serve_socks_udp_vmess(relay, vmess),
        Outbound::Shadowsocks(ss)
            if matches!(ss.carrier, Carrier::Hysteria(_) | Carrier::Xdrive { .. })
                && ss.mux.udp_manager().is_some()
                && ferrox_core::shadowsocks2022::Method::parse(&ss.method).is_none() =>
        {
            serve_socks_udp_shadowsocks(relay, ss);
        }
        Outbound::Shadowsocks(ss) if matches!(ss.carrier, Carrier::Raw(_)) => {
            serve_socks_udp_shadowsocks(relay, ss);
        }
        Outbound::Hysteria(hy) => crate::hysteria_v1::serve_udp(relay, &hy.dial()),
        Outbound::Foxy(foxy) => match foxy.carrier {
            // One tunnel for all destinations: later ones ride the first one opened.
            crate::foxy::Carrier::H3 => serve_socks_udp_foxy_ip(relay, foxy, associate),
            _ => serve_socks_udp_foxy(relay, foxy, associate),
        },
        Outbound::WireGuard(wireguard) => wireguard.serve_udp(relay, associate),
        Outbound::Masque(masque) => masque.serve_udp(relay, associate),
        Outbound::Warp(warp) => warp.serve_udp(relay, associate),
        Outbound::Freedom(out) => {
            serve_socks_udp_freedom(relay, out, source, sockopts, associate);
        }
        Outbound::Socks(socks) => {
            if socks.version == crate::socks::Version::V4 {
                // SOCKS4 has no datagram half: the association is a SOCKS5 request.
                return;
            }
            let Some(server) = resolve_outbound(&socks.address, socks.port) else {
                return;
            };
            serve_socks_udp_client(relay, server, &socks.credential, socks.version, associate);
        }
        Outbound::Psiphon(lane) => {
            serve_socks_udp_client(
                relay,
                lane.endpoint(),
                lane.credential(),
                lane.version(),
                associate,
            );
        }
        Outbound::Dns(dns) => serve_dns_udp(relay, dns),
        Outbound::ReversePortal(portal) => serve_socks_udp_portal(relay, portal),
        _ => {}
    }
}

/// A datagram flow the rules routed to a portal: one mux UDP flow per destination, its replies
/// framed back to the client that sent the datagram.
fn serve_socks_udp_portal(relay: &UdpSocket, portal: &crate::reverse::Portal) {
    struct Lane {
        session: Arc<crate::reverse::Session>,
        id: u16,
        pump: thread::JoinHandle<()>,
    }
    // The map answers a datagram's key in one probe; `order` keeps insertion order for the teardown ends.
    let mut lanes: HashMap<SocketAddr, Lane> = HashMap::new();
    let mut order: Vec<SocketAddr> = Vec::new();
    let mut buf = udp_buffer();
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        let sent = {
            let lane = match lanes.entry(dest) {
                std::collections::hash_map::Entry::Occupied(lane) => lane.into_mut(),
                std::collections::hash_map::Entry::Vacant(lane) => {
                    let Some(session) = portal.pick() else {
                        eprintln!(
                            "reverse: portal `{}` has no live session, so the datagram is dropped",
                            portal.tag()
                        );
                        continue;
                    };
                    let target = ferrox_core::mux::Target {
                        network: ferrox_core::mux::Network::Udp,
                        port: dest.port(),
                        addr: match dest.ip() {
                            std::net::IpAddr::V4(ip) => ferrox_core::addr::Addr::V4(ip.octets()),
                            std::net::IpAddr::V6(ip) => ferrox_core::addr::Addr::V6(ip.octets()),
                        },
                    };
                    let opened = session.open(target, ferrox_core::mux::DEFAULT_CAP as u32);
                    let Some((id, flow)) = opened else {
                        continue;
                    };
                    let Ok(output) = relay.try_clone() else {
                        session.end(id);
                        continue;
                    };
                    let replies = session.clone();
                    let client_addr = src;
                    let pump = thread::spawn(move || {
                        let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
                        while let Ok((data, from)) = flow.down.recv() {
                            // The header names the sender the bridge saw, so the datagram reads as coming from the address that answered.
                            let sender = from.unwrap_or(dest);
                            let frame = socks_udp_frame(&mut frame, &sender, &data);
                            if output.send_to(frame, client_addr).is_err() {
                                break;
                            }
                        }
                        replies.end(id);
                    });
                    order.push(dest);
                    lane.insert(Lane { session, id, pump })
                }
            };
            lane.session.send(lane.id, payload)
        };
        if let Some(lane) = (!sent).then(|| lanes.remove(&dest)).flatten() {
            lane.session.end(lane.id);
            let _ = lane.pump.join();
            order.retain(|known| *known != dest);
        }
    }
    for dest in order {
        if let Some(lane) = lanes.remove(&dest) {
            lane.session.end(lane.id);
            let _ = lane.pump.join();
        }
    }
}

/// A datagram names its own destination, so a ruleset that can name different outbounds gets one
/// lane per chosen tag and the datagram goes to the lane its destination picked. Each lane is the
/// same relay the unsplit association runs, fed by the outer relay and answering through it.
struct UdpLane {
    address: SocketAddr,
    handle: thread::JoinHandle<()>,
    waker: UdpSocket,
}

#[allow(clippy::too_many_lines)]
fn serve_socks_udp_split(
    mut client: Connection,
    plan: &RoutePlan,
    user: Option<&str>,
    level: Option<u32>,
) {
    let Some(relay) = socks_udp_relay(&mut client) else {
        return;
    };
    let _ = relay.set_read_timeout(Some(UDP_POLL));
    let _ = client.set_read_timeout(Some(UDP_POLL));
    let relay_local = relay.local_addr().ok();
    let local = relay
        .local_addr()
        .map_or(std::net::IpAddr::V4([127, 0, 0, 1].into()), |addr| {
            addr.ip()
        });
    let mut lanes: HashMap<String, UdpLane> = HashMap::new();
    let mut default_lane: Option<UdpLane> = None;
    let mut replies: HashSet<SocketAddr> = HashSet::new();
    let mut client_addr: Option<SocketAddr> = None;
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    let mut process = None;
    let mut process_src = None;
    let mut quiet = Instant::now();
    let mut checked = Instant::now();
    loop {
        if checked.elapsed() >= UDP_POLL {
            checked = Instant::now();
            if peer_left(&client) {
                break;
            }
        }
        match relay.recv_from(&mut buf) {
            Ok((n, src)) => {
                quiet = Instant::now();
                if replies.contains(&src) {
                    if let Some(client) = client_addr {
                        let _ = relay.send_to(&buf[..n], client);
                    }
                    continue;
                }
                let Some((dest, payload)) = parse_socks_udp_dest(&buf[..n]) else {
                    continue;
                };
                let mut overridden = None;
                let mut dial = None;
                let mut protocol = None;
                let mut route_only = None;
                if let Some(sniffing) =
                    crate::sniff::current().filter(|sniffing| sniffing.enabled())
                {
                    if let Some(found) = sniffing.inspect_udp(&dest, payload) {
                        protocol = Some(found.protocol);
                        if found.override_destination {
                            let dial_override = sniffing.should_dial_override(&found);
                            overridden = Some(Destination::Name(found.domain, dest.port()));
                            let route = overridden.as_ref().expect("just set");
                            if dial_override {
                                dial = route.socket();
                            } else {
                                route_only = Some(route);
                            }
                        }
                    }
                }
                let route = overridden.as_ref().unwrap_or(&dest);
                client_addr = Some(src);
                if process_src != Some(src) {
                    process = plan.process_owner_from(crate::router::Network::Udp, src);
                    process_src = Some(src);
                }
                let (out, key) = plan.lane_with_protocol(
                    route,
                    crate::router::Network::Udp,
                    Some(&client),
                    FlowFacts {
                        source: Some(src),
                        local: relay_local,
                        protocol,
                        user,
                        level,
                        attrs: None,
                        process: process.as_ref(),
                        original: Some(&dest),
                        route: route_only,
                    },
                );
                if matches!(&*out, Outbound::Block(_)) {
                    continue;
                }
                let lane_address = if let Some(tag) = key.as_deref() {
                    match retire_finished_lane(&mut lanes, &mut replies, tag) {
                        Some(address) => Some(address),
                        None => spawn_udp_lane(&out, local, client.try_clone().ok()).map(|lane| {
                            replies.insert(lane.address);
                            let address = lane.address;
                            lanes.insert(tag.to_owned(), lane);
                            address
                        }),
                    }
                } else {
                    default_udp_lane(
                        &mut default_lane,
                        &mut replies,
                        &out,
                        local,
                        client.try_clone().ok(),
                    )
                };
                if let Some(lane_address) = lane_address {
                    let frame = match dial {
                        Some(address) => socks_udp_frame(&mut frame, &address, payload),
                        None => &buf[..n],
                    };
                    let _ = relay.send_to(frame, lane_address);
                }
            }
            Err(error) => {
                if !is_timeout(&error) || quiet.elapsed() >= budgets::udp_idle() {
                    break;
                }
            }
        }
    }
    retire_udp_lanes(relay, lanes, default_lane);
}

/// The upstream socket's family follows the relay's: an IPv4 relay gets an unspecified IPv4 bind, an IPv6 relay an unspecified IPv6 bind.
fn udp_bind_for(relay: SocketAddr) -> SocketAddr {
    match relay {
        SocketAddr::V4(_) => {
            SocketAddr::new(std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED), 0)
        }
        SocketAddr::V6(_) => {
            SocketAddr::new(std::net::IpAddr::V6(std::net::Ipv6Addr::UNSPECIFIED), 0)
        }
    }
}

/// A lane's loop ends on its own idle or a refused upstream; the tag must not keep writing to the
/// socket nobody reads, so a later datagram for it opens a fresh lane.
fn retire_finished_lane(
    lanes: &mut HashMap<String, UdpLane>,
    replies: &mut HashSet<SocketAddr>,
    key: &str,
) -> Option<SocketAddr> {
    let lane = lanes.get(key)?;
    if !lane.handle.is_finished() {
        return Some(lane.address);
    }
    if let Some(lane) = lanes.remove(key) {
        replies.remove(&lane.address);
    }
    None
}

/// The untagged lane is not a map key: an outbound tag may be any string, so the default lives
/// beside the tag map and only a real tag can own a named lane.
fn default_udp_lane(
    lane: &mut Option<UdpLane>,
    replies: &mut HashSet<SocketAddr>,
    out: &Outbound,
    local: std::net::IpAddr,
    associate: Option<Connection>,
) -> Option<SocketAddr> {
    if let Some(running) = lane.as_ref().filter(|lane| !lane.handle.is_finished()) {
        return Some(running.address);
    }
    if let Some(finished) = lane.take() {
        replies.remove(&finished.address);
    }
    let spawned = spawn_udp_lane(out, local, associate)?;
    replies.insert(spawned.address);
    let address = spawned.address;
    *lane = Some(spawned);
    Some(address)
}

fn arm_control(associate: Option<&Connection>) {
    if let Some(associate) = associate {
        let _ = associate.set_read_timeout(Some(UDP_POLL));
    }
}

fn spawn_udp_lane(
    out: &Outbound,
    local: std::net::IpAddr,
    associate: Option<Connection>,
) -> Option<UdpLane> {
    let socket = UdpSocket::bind(SocketAddr::new(local, 0)).ok()?;
    let address = socket.local_addr().ok()?;
    let waker = socket.try_clone().ok()?;
    let _ = socket.set_read_timeout(Some(budgets::udp_idle()));
    arm_control(associate.as_ref());
    let source = SEND_THROUGH.with(std::cell::Cell::take);
    let sockopts = DIAL_SOCKOPTS.with(|cell| cell.borrow_mut().take());
    let out = out.clone();
    let handle = thread::spawn(move || {
        // The lane's own thread starts with the settings the pick left on this one.
        SEND_THROUGH.with(|cell| cell.set(source));
        DIAL_SOCKOPTS.with(|cell| *cell.borrow_mut() = sockopts);
        serve_udp_lane(&socket, &out, associate.as_ref());
    });
    Some(UdpLane {
        address,
        handle,
        waker,
    })
}

/// An association that owns its lanes: when it ends, each lane is woken with a datagram that names
/// no destination and its read timeout is shortened, while the relay stays bound until every lane
/// has joined so a late answer cannot reach a later association on the reused port.
fn retire_udp_lanes(
    relay: UdpSocket,
    lanes: HashMap<String, UdpLane>,
    default_lane: Option<UdpLane>,
) {
    if lanes.is_empty() && default_lane.is_none() {
        return;
    }
    thread::spawn(move || {
        for lane in lanes.values().chain(default_lane.iter()) {
            let _ = lane.waker.set_read_timeout(Some(UDP_POLL));
            let _ = relay.send_to(&[0u8], lane.address);
        }
        for lane in lanes.into_values().chain(default_lane) {
            let _ = lane.handle.join();
        }
    });
}

/// The SOCKS5 client lane for datagrams: one association to the upstream server, and
/// every datagram rides it framed the way RFC 1928 frames them.
///
/// The control leg stays open for the association's life: dropping it ends the
/// association, and the server stops relaying.
fn serve_socks_udp_client(
    relay: &UdpSocket,
    server: SocketAddr,
    credential: &crate::socks::Credential,
    version: crate::socks::Version,
    associate: Option<&Connection>,
) {
    if version == crate::socks::Version::V4 {
        return;
    }
    let idle = lane_idle(relay);
    let Some(stream) = dial_or_report(&server) else {
        return;
    };
    let read = stream.read_timeout().ok().flatten();
    let _ = stream.set_read_timeout(Some(budgets::handshake()));
    let _ = stream.set_write_timeout(Some(budgets::handshake()));
    let Some(association) = crate::socks::associate(stream, credential) else {
        return;
    };
    let control = association.control;
    let peer = control_peer(associate);
    let mut pinned = None;
    let poll = lane_poll(read);
    let _ = control.set_read_timeout(Some(poll));
    let _ = control.set_write_timeout(None);
    if let Some(associate) = associate {
        let _ = associate.set_read_timeout(Some(budgets::SESSION_POLL));
    }
    let Ok(upstream) = UdpSocket::bind(udp_bind_for(association.relay)) else {
        return;
    };
    if upstream.connect(association.relay).is_err() {
        return;
    }
    // The poll is the lane's own: the request leg checks the control socket and the idle budget, and the answer leg checks the stop flag.
    let _ = relay.set_read_timeout(Some(UDP_POLL));
    let _ = upstream.set_read_timeout(Some(UDP_POLL));
    let Ok(sender) = upstream.try_clone() else {
        return;
    };
    let Ok(receiver) = upstream.try_clone() else {
        return;
    };
    let Ok(client) = relay.try_clone() else {
        return;
    };
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let reader_source = source.clone();
    let activity = Arc::new(Mutex::new(Instant::now()));
    let answer_activity = activity.clone();
    let done = Arc::new(AtomicBool::new(false));
    let answer_done = done.clone();
    // The answer leg: the upstream's frames go back to the client that sent them.
    let answer = thread::spawn(move || {
        serve_udp_answer(
            &receiver,
            &client,
            &reader_source,
            &answer_done,
            &answer_activity,
        );
    });
    // The request leg: the client's frames go to the relay address the server named.
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    loop {
        match relay.recv_from(&mut buf) {
            Ok((n, src)) => {
                let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
                    continue;
                };
                if payload.is_empty() {
                    continue;
                }
                if !source_allowed(peer, &mut pinned, &source, src) {
                    continue;
                }
                touch(&activity);
                let forwarded = socks_udp_forwarded(&buf[..n], &dest, payload);
                let sent = if let Some(whole) = forwarded {
                    sender.send(whole).is_ok()
                } else {
                    let (front, tail) = socks_udp_parts(&mut frame, &dest, payload);
                    send_two(&sender, front, tail).is_ok()
                };
                if !sent {
                    break;
                }
            }
            Err(error) if is_timeout(&error) || is_udp_gone(&error) => {
                if is_udp_gone(&error) {
                    thread::sleep(UDP_POLL);
                }
                if peer_left(&control)
                    || associate.is_some_and(peer_left)
                    || idle_for(&activity) >= idle
                {
                    break;
                }
            }
            Err(_) => break,
        }
    }
    done.store(true, Ordering::Relaxed);
    let _ = answer.join();
}

/// The peer of the association's control socket: a datagram from any other IP is not this client.
fn control_peer(associate: Option<&Connection>) -> Option<IpAddr> {
    associate
        .and_then(|client| client.peer_addr().ok())
        .map(|address| address.ip().to_canonical())
}

/// A datagram belongs to the association only if it comes from the control peer and, after the first, from the same UDP source the client pinned.
fn source_allowed(
    peer: Option<IpAddr>,
    pinned: &mut Option<SocketAddr>,
    source: &Mutex<Option<SocketAddr>>,
    datagram: SocketAddr,
) -> bool {
    if peer.is_some_and(|peer| datagram.ip().to_canonical() != peer) {
        return false;
    }
    if let Some(allowed) = *pinned {
        return allowed == datagram;
    }
    *pinned = Some(datagram);
    if let Ok(mut slot) = source.lock() {
        *slot = Some(datagram);
    }
    true
}

/// The lane's idle is measured from the last datagram in either direction.
fn idle_for(activity: &Mutex<Instant>) -> Duration {
    activity
        .lock()
        .map(|last| last.elapsed())
        .unwrap_or_default()
}

/// A datagram in either direction is activity: the lane's idle budget measures silence, not a request without a reply.
fn touch(activity: &Mutex<Instant>) {
    if let Ok(mut last) = activity.lock() {
        *last = Instant::now();
    }
}

/// The control socket is polled for closure: the caller's read timeout still bounds the wait, but never beyond one session poll.
fn lane_poll(read: Option<Duration>) -> Duration {
    read.map_or(budgets::SESSION_POLL, |limit| {
        limit.min(budgets::SESSION_POLL)
    })
}

/// The lane's idle is the caller's read timeout, capped at the tree's UDP idle: a DNS query's short timeout is not replaced by the long one.
fn lane_idle(relay: &UdpSocket) -> Duration {
    relay
        .read_timeout()
        .ok()
        .flatten()
        .map_or(budgets::udp_idle(), |limit| limit.min(budgets::udp_idle()))
}

/// The answer leg of a SOCKS client lane: the upstream's frames go back to the client that sent them, and a stop flag ends the read poll.
fn serve_udp_answer(
    receiver: &UdpSocket,
    client: &UdpSocket,
    source: &Mutex<Option<SocketAddr>>,
    done: &AtomicBool,
    activity: &Mutex<Instant>,
) {
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    while !done.load(Ordering::Relaxed) {
        let (n, _) = match receiver.recv_from(&mut buf) {
            Ok(read) => read,
            Err(error) if is_timeout(&error) => continue,
            Err(error) if is_udp_gone(&error) => {
                thread::sleep(UDP_POLL);
                if done.load(Ordering::Relaxed) {
                    break;
                }
                continue;
            }
            Err(_) => break,
        };
        let Some((from, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        let Some(dest) = source.lock().ok().and_then(|slot| *slot) else {
            continue;
        };
        let forwarded = socks_udp_forwarded(&buf[..n], &from, payload);
        let sent = if let Some(whole) = forwarded {
            client.send_to(whole, dest).is_ok()
        } else {
            let (front, tail) = socks_udp_parts(&mut frame, &from, payload);
            send_to_two(client, front, tail, dest).is_ok()
        };
        if !sent {
            break;
        }
        touch(activity);
    }
}

/// One datagram socket for a direct destination: the family it dials, the source the outbound
/// names, and the options the outbound took, all before the first packet.
fn datagram_uplink(
    dest: SocketAddr,
    send_through: Option<SendThrough>,
    sockopts: Option<&crate::sockopt::SocketOptions>,
) -> Option<(UdpSocket, Option<Arc<AtomicBool>>)> {
    use socket2::{Domain, Protocol, SockAddr, Socket, Type};
    if let Some(options) = sockopts {
        if let Some(tag) = options.dialer_proxy() {
            return dial_udp_through_proxy(dest, tag, options)
                .map(|(socket, stop)| (socket, Some(stop)));
        }
    }
    let source = resolve_source(send_through).ok()?;
    let domain = if dest.is_ipv4() {
        Domain::IPV4
    } else {
        Domain::IPV6
    };
    let socket = Socket::new(domain, Type::DGRAM, Some(Protocol::UDP)).ok()?;
    if let Some(sockopts) = sockopts {
        sockopts.apply_to_datagram(&socket, dest).ok()?;
    }
    let bind = source.map_or_else(
        || {
            let any = if dest.is_ipv4() {
                IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED)
            } else {
                IpAddr::V6(std::net::Ipv6Addr::UNSPECIFIED)
            };
            SocketAddr::new(any, 0)
        },
        |source| SocketAddr::new(source, 0),
    );
    socket.bind(&SockAddr::from(bind)).ok()?;
    socket.set_read_timeout(Some(budgets::udp_idle())).ok()?;
    socket.connect(&SockAddr::from(dest)).ok()?;
    Some((UdpSocket::from(socket), None))
}

/// Freedom UDP: the machine's own socket per destination, since a datagram here has no carrier to ride.
fn serve_socks_udp_freedom(
    relay: &UdpSocket,
    freedom: &FreedomOut,
    send_through: Option<SendThrough>,
    sockopts: Option<&crate::sockopt::SocketOptions>,
    associate: Option<&Connection>,
) {
    arm_control(associate);
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let replies = Arc::new(AtomicU64::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let mut pinned = None;
    let mut uplinks: HashMap<SocketAddr, FreedomUplink> = HashMap::new();
    let mut buf = udp_buffer();
    let mut seen = 0u64;
    loop {
        let (n, src) = match relay.recv_from(&mut buf) {
            Ok(read) => read,
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) || is_udp_gone(&error) =>
            {
                let now = replies.load(Ordering::Relaxed);
                if associate.is_some_and(peer_left) || now == seen {
                    break;
                }
                seen = now;
                continue;
            }
            Err(_) => break,
        };
        seen = replies.load(Ordering::Relaxed);
        // The first sender is the relay's peer; a later one cannot redirect the replies.
        if !source_allowed(None, &mut pinned, &source, src) {
            continue;
        }
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        let Some(dest) = freedom_socket(freedom, &Destination::Address(dest)) else {
            continue;
        };
        let blocked = freedom.blocks(crate::router::Network::Udp, dest.ip(), dest.port());
        if let Some((socket, _, gate, _)) = uplinks.get(&dest) {
            if blocked {
                continue;
            }
            let mut gate = gate
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            if gate.failed {
                continue;
            }
            if gate.ready {
                drop(gate);
                let _ = socket.send(payload);
            } else {
                gate.queue(payload);
            }
            continue;
        }
        let Some((up, tagged_stop)) = datagram_uplink(dest, send_through, sockopts) else {
            continue;
        };
        let (Ok(writer), Ok(relay_write), Ok(noise_socket)) =
            (up.try_clone(), relay.try_clone(), up.try_clone())
        else {
            if let Some(stop) = &tagged_stop {
                stop.store(true, Ordering::Relaxed);
            }
            continue;
        };
        let gate = Arc::new(Mutex::new(FreedomNoiseGate {
            ready: false,
            failed: false,
            pending: if blocked {
                Vec::new()
            } else {
                vec![payload.to_vec()]
            },
        }));
        let done = freedom_reader(
            up,
            Arc::clone(&source),
            relay_write,
            Arc::clone(&replies),
            dest,
            Arc::clone(&stop),
        );
        uplinks.insert(dest, (writer, done, Arc::clone(&gate), tagged_stop));
        start_freedom_noises(
            freedom.noises.clone(),
            freedom.override_port() == 53,
            noise_socket,
            dest,
            gate,
        );
    }
    retire_freedom_uplinks(uplinks, &stop);
}

fn retire_freedom_uplinks(uplinks: HashMap<SocketAddr, FreedomUplink>, stop: &AtomicBool) {
    stop.store(true, Ordering::Relaxed);
    for (_, (writer, handle, _, tagged_stop)) in uplinks {
        if let Some(stop) = tagged_stop {
            stop.store(true, Ordering::Relaxed);
        }
        let _ = writer.set_read_timeout(Some(UDP_POLL));
        let _ = handle.join();
    }
}

type FreedomUplink = (
    UdpSocket,
    thread::JoinHandle<()>,
    Arc<Mutex<FreedomNoiseGate>>,
    Option<Arc<AtomicBool>>,
);

/// The decoys run on their own thread so one new destination's wait does not stall the rest.
fn start_freedom_noises(
    noises: Vec<FreedomNoise>,
    skip_dns: bool,
    socket: UdpSocket,
    dest: SocketAddr,
    gate: Arc<Mutex<FreedomNoiseGate>>,
) {
    thread::spawn(move || {
        let sent = send_freedom_noises(&noises, skip_dns, &socket, dest);
        let mut gate = gate
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !sent {
            gate.failed = true;
            gate.pending.clear();
            return;
        }
        for packet in gate.pending.drain(..) {
            let _ = socket.send(&packet);
        }
        gate.ready = true;
    });
}

/// One destination's replies, framed back to whichever client datagram most recently named it.
fn freedom_reader(
    socket: UdpSocket,
    source: Arc<Mutex<Option<SocketAddr>>>,
    relay: UdpSocket,
    replies: Arc<AtomicU64>,
    dest: SocketAddr,
    stop: Arc<AtomicBool>,
) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        let mut back = udp_buffer();
        let mut framed = Vec::with_capacity(HEAD + UDP_BUF);
        while !stop.load(Ordering::Relaxed) {
            let Ok(read) = socket.recv(&mut back) else {
                break;
            };
            if stop.load(Ordering::Relaxed) {
                break;
            }
            let Some(source) = source.lock().ok().and_then(|slot| *slot) else {
                continue;
            };
            let out = socks_udp_frame(&mut framed, &dest, &back[..read]);
            if relay.send_to(out, source).is_err() {
                break;
            }
            replies.fetch_add(1, Ordering::Relaxed);
        }
    })
}

/// The association's control socket answers a peek with zero (or an error) once the app is gone; a timeout is the answer that says it is still there.
pub(crate) fn peer_left(associate: &Connection) -> bool {
    let mut byte = [0u8; 1];
    match associate.peek(&mut byte) {
        Err(error) => !is_timeout(&error),
        Ok(read) => read == 0,
    }
}

/// The association's own tick: how long the relay socket waits for a datagram and how long any lane it reads waits for a packet, so one silent stream cannot cost a pass more than the tick.
const UDP_POLL: Duration = Duration::from_millis(10);

/// Datagrams one side may take per pass, so a burst is served in one pass and neither direction starves the other.
const UDP_BURST: usize = 64;

/// The DNS lane's idle: the reference's session-default `ConnectionIdle`; the tree carries no policy app to name another.
const DNS_IDLE: Duration = Duration::from_secs(300);

/// The upstream lane the direct half rides: a stream the DNS framing carries, or a socket that answers each datagram.
enum DnsUpstream {
    Tcp(Connection),
    Udp(UdpSocket),
}

/// One message the source network's own frame carries: a length-prefixed read into the caller's
/// buffer — the lane reads every message into the one it already owns — and the message's span in it.
fn read_dns_source<'a>(stream: &mut impl Read, body: &'a mut Vec<u8>) -> Option<&'a [u8]> {
    let mut head = [0u8; 2];
    stream.read_exact(&mut head).ok()?;
    let size = usize::from(u16::from_be_bytes(head));
    if size > ferrox_core::dns::MESSAGE_MAX {
        return None;
    }
    resize_scratch(body, size);
    stream.read_exact(body).ok()?;
    Some(body)
}

/// The machine's own resolver, the way the reference's localdns answers: the addrs of the
/// resolved name, the empty response when the name carries none, and the hard error otherwise.
fn dns_lookup(name: &[u8]) -> ferrox_core::dns::Resolve {
    let Some(host) = name
        .strip_suffix(b".")
        .and_then(|name| std::str::from_utf8(name).ok())
    else {
        return ferrox_core::dns::Resolve::ErrHard;
    };
    if let Ok(literal) = host.parse::<std::net::IpAddr>() {
        // A literal needs no resolver: the parse is the whole lookup.
        let octets = match literal {
            std::net::IpAddr::V4(ip) => ip.octets().to_vec(),
            std::net::IpAddr::V6(ip) => ip.octets().to_vec(),
        };
        return ferrox_core::dns::Resolve::Records {
            rdata: vec![octets],
            ttl: 300,
        };
    }
    if let Some(resolver) = crate::dnsapp::installed() {
        return match resolver.lookup_result(host) {
            crate::dnsapp::Lookup::Records(ips, ttl) => ferrox_core::dns::Resolve::Records {
                rdata: ips
                    .iter()
                    .map(|ip| match ip {
                        std::net::IpAddr::V4(ip) => ip.octets().to_vec(),
                        std::net::IpAddr::V6(ip) => ip.octets().to_vec(),
                    })
                    .collect(),
                ttl,
            },
            crate::dnsapp::Lookup::Empty | crate::dnsapp::Lookup::Skipped => {
                ferrox_core::dns::Resolve::AnsweredEmpty
            }
            crate::dnsapp::Lookup::Rcode(code) => ferrox_core::dns::Resolve::Refused(code),
            crate::dnsapp::Lookup::Failed => ferrox_core::dns::Resolve::ErrHard,
        };
    }
    let addrs = if let Some(addrs) = cached_lookup(host, 0) {
        addrs
    } else {
        let Some(addrs) = resolve_bounded(host, 0, budgets::dial(), |host, port| {
            (host, port)
                .to_socket_addrs()
                .map(std::iter::Iterator::collect)
        }) else {
            return ferrox_core::dns::Resolve::ErrHard;
        };
        remember_lookup(host, 0, &addrs)
    };
    if addrs.is_empty() {
        return ferrox_core::dns::Resolve::AnsweredEmpty;
    }
    ferrox_core::dns::Resolve::Records {
        rdata: addrs
            .iter()
            .map(|addr| match addr.ip() {
                std::net::IpAddr::V4(ip) => ip.octets().to_vec(),
                std::net::IpAddr::V6(ip) => ip.octets().to_vec(),
            })
            .collect(),
        ttl: 300,
    }
}

/// The destination one query rides: the rewrite overlays the destination the flow named, field by field.
fn dns_dest(dns: &DnsOut, asked: &Destination) -> Destination {
    let port = if dns.port != 0 {
        dns.port
    } else {
        asked.port()
    };
    match &dns.address {
        Some(address) => Destination::Name(address.clone(), port),
        None => match asked {
            Destination::Name(host, _) => Destination::Name(host.clone(), port),
            Destination::Address(address) => {
                Destination::Address(SocketAddr::new(address.ip(), port))
            }
        },
    }
}

/// The lane a direct side rides: dialed once on the rewritten destination's own
/// network, its idle the reference's session default on both handles.
fn dial_dns(target: &SocketAddr, tcp: bool) -> Option<DnsUpstream> {
    if tcp {
        let stream = dial_or_report(target)?;
        let _ = stream.set_read_timeout(Some(DNS_IDLE));
        Some(DnsUpstream::Tcp(stream))
    } else {
        let Ok(socket) = UdpSocket::bind(SocketAddr::new(
            std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED),
            0,
        )) else {
            return None;
        };
        let Ok(()) = socket.connect(target) else {
            return None;
        };
        let _ = socket.set_read_timeout(Some(DNS_IDLE));
        Some(DnsUpstream::Udp(socket))
    }
}

/// The answers leg's handle of the dialed lane: a reader of its own, so the queries' writes and the answers' reads never block each other.
fn answer_handle(up: &DnsUpstream) -> Option<DnsUpstream> {
    match up {
        DnsUpstream::Tcp(stream) => stream.try_clone().ok().map(DnsUpstream::Tcp),
        DnsUpstream::Udp(socket) => socket.try_clone().ok().map(DnsUpstream::Udp),
    }
}

/// The stream framing: the length then the message, gathered into one `writev`. An empty message rides nothing, the way the reference's writer answers one.
fn write_dns_frame(stream: &mut Connection, message: &[u8]) -> bool {
    if message.is_empty() {
        return true;
    }
    let head = (message.len() as u16).to_be_bytes();
    write_all_parts::<2>(stream, &[&head, message]).is_ok()
}

/// One query onto the lane the rewrite named: the stream carries the framing, the socket one datagram.
fn send_dns_query(up: &mut DnsUpstream, message: &[u8]) -> bool {
    match up {
        DnsUpstream::Tcp(stream) => write_dns_frame(stream, message),
        DnsUpstream::Udp(socket) => socket.send(message).is_ok(),
    }
}

/// The DNS outbound's stream lane: the client's framed queries decide one by
/// one, a hijack answers with the resolver in place, a direct query rides the
/// rewritten lane, and the upstream's answers relay back framed the way the
/// client framed them. The queries leg owns the client's read side; the
/// answers leg its own write handle and reader.
fn serve_dns_tcp(mut client: Connection, dns: &DnsOut, asked: &Destination) {
    let _ = client.set_read_timeout(Some(DNS_IDLE));
    let dest = dns_dest(dns, asked);
    let Ok(to_client) = client.try_clone() else {
        return;
    };
    let (ready, reader_at) = std::sync::mpsc::sync_channel::<DnsUpstream>(1);
    let Ok(leg) = thread::Builder::new()
        .name("ferrox-dns-answer".to_owned())
        .spawn(move || {
            // The answers leg waits on the lane's dial, the readiness the reference's own conn waits on; a closed channel is the queries leg's end.
            let Ok(mut reader) = reader_at.recv() else {
                return;
            };
            let mut sink = to_client;
            let mut back = udp_buffer();
            let mut body = Vec::new();
            loop {
                let wrote = match &mut reader {
                    DnsUpstream::Tcp(stream) => match read_dns_source(stream, &mut body) {
                        Some(message) => write_dns_frame(&mut sink, message),
                        None => return,
                    },
                    DnsUpstream::Udp(socket) => match socket.recv(&mut back) {
                        Ok(read) => write_dns_frame(&mut sink, &back[..read]),
                        Err(_) => return,
                    },
                };
                if !wrote {
                    return;
                }
            }
        })
    else {
        return;
    };
    let mut lane: Option<DnsUpstream> = None;
    let mut body = Vec::new();
    while let Some(message) = read_dns_source(&mut client, &mut body) {
        match ferrox_core::dns::decide(message, &dns.rules, &dns_lookup) {
            ferrox_core::dns::Step::Quiet => {}
            ferrox_core::dns::Step::Reply(answer) => {
                if !write_dns_frame(&mut client, &answer) {
                    return;
                }
            }
            ferrox_core::dns::Step::Forward => {
                if lane.is_none() {
                    let Some(target) = dest.socket() else {
                        return;
                    };
                    let Some(up) = dial_dns(&target, dns.tcp.unwrap_or(true)) else {
                        return;
                    };
                    let Some(reader) = answer_handle(&up) else {
                        return;
                    };
                    if ready.send(reader).is_err() {
                        return;
                    }
                    lane = Some(up);
                }
                let Some(up) = lane.as_mut() else {
                    continue;
                };
                if !send_dns_query(up, message) {
                    return;
                }
            }
        }
    }
    let _ = leg;
}

/// The DNS outbound's datagram lane: the association's queries decide one by
/// one, a hijack answers the source in place, and a direct datagram rides the
/// rewritten lane the first one named. Each answer goes back framed to the
/// socket the datagram came from.
fn serve_dns_udp(relay: &UdpSocket, dns: &DnsOut) {
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let mut lanes: HashMap<SocketAddr, (DnsUpstream, thread::JoinHandle<()>)> = HashMap::new();
    let mut buf = udp_buffer();
    let mut frame = Vec::with_capacity(HEAD + UDP_BUF);
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if let Ok(mut slot) = source.lock() {
            *slot = Some(src);
        }
        match ferrox_core::dns::decide(payload, &dns.rules, &dns_lookup) {
            ferrox_core::dns::Step::Quiet => {}
            ferrox_core::dns::Step::Reply(answer) => {
                let out = socks_udp_frame(&mut frame, &dest, &answer);
                if relay.send_to(out, src).is_err() {
                    break;
                }
            }
            ferrox_core::dns::Step::Forward => {
                let target = dns_dest(dns, &Destination::Address(dest));
                let Some(up_addr) = target.socket() else {
                    continue;
                };
                if let Some((lane, _)) = lanes.get_mut(&up_addr) {
                    let _ = send_dns_query(lane, payload);
                    continue;
                }
                let Some(up) = dial_dns(&up_addr, dns.tcp.unwrap_or(false)) else {
                    continue;
                };
                let Some(reader) = answer_handle(&up) else {
                    continue;
                };
                let named = dest;
                let peer = source.clone();
                let Ok(relay_write) = relay.try_clone() else {
                    continue;
                };
                let Ok(done) = thread::Builder::new()
                    .name("ferrox-dns-answer".to_owned())
                    .spawn(move || {
                        let mut to_up = reader;
                        let mut back = udp_buffer();
                        let mut body = Vec::new();
                        let mut framed = Vec::with_capacity(HEAD + UDP_BUF);
                        loop {
                            let wrote = match &mut to_up {
                                DnsUpstream::Tcp(stream) => {
                                    match read_dns_source(stream, &mut body) {
                                        Some(message) => {
                                            let out = socks_udp_frame(&mut framed, &named, message);
                                            let Some(src) = peer.lock().ok().and_then(|slot| *slot)
                                            else {
                                                continue;
                                            };
                                            relay_write.send_to(out, src).is_ok()
                                        }
                                        None => false,
                                    }
                                }
                                DnsUpstream::Udp(socket) => match socket.recv(&mut back) {
                                    Ok(read) => {
                                        let out =
                                            socks_udp_frame(&mut framed, &named, &back[..read]);
                                        let Some(src) = peer.lock().ok().and_then(|slot| *slot)
                                        else {
                                            continue;
                                        };
                                        relay_write.send_to(out, src).is_ok()
                                    }
                                    Err(_) => false,
                                },
                            };
                            if !wrote {
                                break;
                            }
                        }
                    })
                else {
                    continue;
                };
                lanes.insert(up_addr, (up, done));
                // The datagram that opened the lane is its first payload; a hop must not drop it.
                if let Some((lane, _)) = lanes.get_mut(&up_addr) {
                    let _ = send_dns_query(lane, payload);
                }
            }
        }
    }
    for (_, (_, handle)) in lanes {
        // The relayed datagrams are on their own sockets, so this exit is their idle timeout.
        let _ = handle.join();
    }
}

/// Foxy UDP: one CONNECT-UDP stream per destination, HTTP/2 then HTTP/3; the configured carrier does not apply.
fn serve_socks_udp_foxy(relay: &UdpSocket, foxy: &FoxyOut, associate: Option<&Connection>) {
    let _ = relay.set_read_timeout(Some(UDP_POLL));
    if let Some(associate) = associate {
        let _ = associate.set_read_timeout(Some(budgets::SESSION_POLL));
    }
    let mut streams: HashMap<SocketAddr, crate::foxy::Datagram> = HashMap::new();
    let mut buf = udp_buffer();
    let mut datagram = udp_buffer();
    let mut reply = Vec::with_capacity(UDP_BUF);
    let mut client = None;
    let mut quiet = Instant::now();
    loop {
        // The client's datagrams go out as a burst: one per pass would pace the upload at the tick, and a burst is what an app sends.
        let mut ended = false;
        for _ in 0..UDP_BURST {
            match relay.recv_from(&mut buf) {
                Ok((n, src)) => {
                    quiet = Instant::now();
                    client = Some(src);
                    let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
                        continue;
                    };
                    if payload.is_empty() {
                        continue;
                    }
                    if let std::collections::hash_map::Entry::Vacant(slot) = streams.entry(dest) {
                        if let Some(lane) = foxy_udp_dial(foxy, &dest) {
                            slot.insert(lane);
                        }
                    }
                    if let Some(lane) = streams.get_mut(&dest) {
                        match lane.write(payload) {
                            // A lane whose credit the edge has not granted yet loses the datagram rather than the lane: reading is what earns the grant back, and this pass reads for every stream below.
                            Err(error) if is_timeout(&error) => {}
                            Err(_) => {
                                streams.remove(&dest);
                            }
                            Ok(_) => {}
                        }
                    }
                }
                Err(error) if is_timeout(&error) => {
                    ended =
                        associate.is_some_and(peer_left) || quiet.elapsed() >= budgets::udp_idle();
                    break;
                }
                Err(_) => {
                    ended = true;
                    break;
                }
            }
        }
        if ended {
            break;
        }
        let mut dead = Vec::new();
        for (dest, lane) in &mut streams {
            for _ in 0..UDP_BURST {
                match lane.read(&mut datagram) {
                    // A stream the edge closed is gone: the next datagram for that destination dials a fresh one.
                    Ok(0) => {
                        dead.push(*dest);
                        break;
                    }
                    Ok(n) => {
                        quiet = Instant::now();
                        if let Some(src) = client {
                            let out = socks_udp_frame(&mut reply, dest, &datagram[..n]);
                            let _ = relay.send_to(out, src);
                        }
                    }
                    Err(error) if is_timeout(&error) => break,
                    Err(_) => {
                        dead.push(*dest);
                        break;
                    }
                }
            }
        }
        for dest in dead {
            streams.remove(&dest);
        }
    }
}

/// CONNECT-IP UDP: one tunnel shared by every destination, so later targets cost a map row, not a dial.
fn serve_socks_udp_foxy_ip(relay: &UdpSocket, foxy: &FoxyOut, associate: Option<&Connection>) {
    let _ = relay.set_read_timeout(Some(UDP_POLL));
    if let Some(associate) = associate {
        let _ = associate.set_read_timeout(Some(budgets::SESSION_POLL));
    }
    // The tunnel and its owned source address are opened once and shared: that is this row's whole point.
    let mut tunnel: Option<crate::foxy::Ip> = None;
    let mut source = [0u8; 16];
    let mut width = 0usize;
    let mut buf = udp_buffer();
    let mut reply = Vec::with_capacity(UDP_BUF);
    let mut packet = Vec::with_capacity(UDP_BUF);
    let mut client = None;
    // One port per destination so a reply lands where it was sent from: the address is shared, the port is not.
    let mut ports: HashMap<SocketAddr, u16> = HashMap::new();
    let mut next_port = 40_000u16;
    let mut quiet = Instant::now();
    loop {
        // The client's datagrams go out as a burst, and the destination address rides a stack buffer: one packet per pass and one `Vec` per packet are both a cost the association has no reason to pay.
        let mut ended = false;
        for _ in 0..UDP_BURST {
            match relay.recv_from(&mut buf) {
                Ok((n, src)) => {
                    quiet = Instant::now();
                    client = Some(src);
                    let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
                        continue;
                    };
                    if payload.is_empty() {
                        continue;
                    }
                    if width == 0
                        && !open_foxy_ip_tunnel(foxy, &mut tunnel, &mut source, &mut width)
                    {
                        continue;
                    }
                    let Some(port) = ports.get(&dest).copied().or_else(|| {
                        let port = next_port;
                        next_port = next_port.wrapping_add(1).max(1);
                        ports.insert(dest, port);
                        Some(port)
                    }) else {
                        continue;
                    };
                    let mut address = [0u8; 16];
                    let destination: &[u8] = match dest.ip() {
                        std::net::IpAddr::V4(ip) => {
                            address[..4].copy_from_slice(&ip.octets());
                            &address[..4]
                        }
                        std::net::IpAddr::V6(ip) => {
                            address.copy_from_slice(&ip.octets());
                            &address
                        }
                    };
                    // The packet's family is the tunnel's: it cannot carry an address the proxy never assigned.
                    if destination.len() != width {
                        continue;
                    }
                    if let Some(lane) = tunnel.as_mut() {
                        if let Err(error) = lane
                            .write(&source[..width], destination, port, dest.port(), payload)
                            .and_then(|_| lane.flush())
                        {
                            // No credit is the lane waiting for a grant the next read pass carries, so the packet is lost and the tunnel is not; only a broken lane is dialled again.
                            if !is_timeout(&error) {
                                tunnel = None;
                                width = 0;
                                ports.clear();
                            }
                        }
                    }
                }
                Err(error) if is_timeout(&error) => {
                    ended =
                        associate.is_some_and(peer_left) || quiet.elapsed() >= budgets::udp_idle();
                    break;
                }
                Err(_) => {
                    ended = true;
                    break;
                }
            }
        }
        if ended {
            break;
        }
        // One pass reads the tunnel until it goes quiet, so a reply burst leaves on the tick it arrived on.
        if let Some(lane) = tunnel.as_mut() {
            match drain_foxy_ip_tunnel(lane, relay, client, &mut reply, &mut packet) {
                Some(0) => {}
                Some(_) => quiet = Instant::now(),
                None => {
                    tunnel = None;
                    width = 0;
                    ports.clear();
                }
            }
        }
    }
}

/// The tunnel's packets, read until it goes quiet and each handed back to the client that sent for its destination: one read per pass would pace a download at one packet per tick. `None` is a tunnel to dial again.
fn drain_foxy_ip_tunnel(
    lane: &mut crate::foxy::Ip,
    relay: &UdpSocket,
    client: Option<SocketAddr>,
    reply: &mut Vec<u8>,
    packet: &mut Vec<u8>,
) -> Option<usize> {
    let mut packets = 0usize;
    for _ in 0..UDP_BURST {
        match lane.read(packet) {
            Ok(true) => {
                packets += 1;
                let Some(read) = ferrox_core::foxy::connectip::udp_from_packet(packet) else {
                    continue;
                };
                if !read.verified {
                    continue;
                }
                let peer = socket_from_bytes(read.source, read.destination);
                if let Some(src) = client {
                    let out = socks_udp_frame(reply, &peer, read.payload);
                    let _ = relay.send_to(out, src);
                }
            }
            Err(error) if is_timeout(&error) => break,
            Ok(false) | Err(_) => return None,
        }
    }
    Some(packets)
}

/// The sender read out of the packet's own source: a v6 destination never sent to is not a peer, a v4 one is.
fn socket_from_bytes(source: &[u8], destination: &[u8]) -> SocketAddr {
    let ip = if destination.len() == 4 {
        std::net::IpAddr::V4(std::net::Ipv4Addr::new(
            source[0], source[1], source[2], source[3],
        ))
    } else {
        let mut octets = [0u8; 16];
        octets.copy_from_slice(&source[..16]);
        std::net::IpAddr::V6(std::net::Ipv6Addr::from(octets))
    };
    SocketAddr::new(ip, 0)
}

/// Opens the tunnel on the first answering edge, HTTP/3 then HTTP/2; no assigned address means refuse, not guess.
fn open_foxy_ip_tunnel(
    foxy: &FoxyOut,
    tunnel: &mut Option<crate::foxy::Ip>,
    source: &mut [u8; 16],
    width: &mut usize,
) -> bool {
    if edge_limited(&foxy.limited_until, now_secs()) {
        return false;
    }
    for edge in ferrox_core::foxy::dial_order(
        &foxy.ladder,
        &foxy.country,
        foxy.stored.as_deref(),
        MAX_FOXY_ALTERNATES,
    ) {
        let pass = foxy
            .account
            .as_ref()
            .map_or_else(|| foxy.pass.clone(), |account| account.current());
        for carrier in crate::foxy::Carrier::ip_order() {
            // As on TCP and CONNECT-UDP: a silent carrier is left alone for the window, not probed per packet.
            if foxy.carrier_unanswered(edge, carrier) {
                continue;
            }
            let dial = crate::foxy::FoxyDial {
                host: edge.host.clone(),
                port: edge.port,
                address: foxy.edge_address,
                carrier,
                upstream: foxy.upstream.clone(),
                roots: foxy.roots.clone(),
                pins: foxy.pins.clone(),
                pass: pass.clone(),
            };
            let quic = match carrier {
                crate::foxy::Carrier::H3 => crate::quic::pooled_stream_within(
                    &foxy_quic_dial(foxy, edge),
                    if foxy.carrier == crate::foxy::Carrier::H3 {
                        crate::quic::HANDSHAKE_TIMEOUT
                    } else {
                        budgets::carrier_probe()
                    },
                ),
                _ => None,
            };
            match crate::foxy::Ip::open(&dial, quic) {
                Ok((mut lane, assigned)) => {
                    debug_lane(edge, carrier, || "connect-ip opened".to_owned());
                    clear_limited(&foxy.limited_strikes, &foxy.limited_until);
                    foxy.carrier_answered(edge, carrier);
                    let Some(granted) = assigned else {
                        debug_lane(edge, carrier, || {
                            "the edge granted no address, so the tunnel carries nothing".to_owned()
                        });
                        continue;
                    };
                    *width = granted.width();
                    source[..*width].copy_from_slice(granted.bytes());
                    // The tunnel read waits no longer than the association's own tick: a longer quantum paces every upload at one packet per wait.
                    let _ = lane.set_read_quantum(UDP_POLL);
                    *tunnel = Some(lane);
                    return true;
                }
                Err(failure) => {
                    debug_lane(edge, carrier, || failure.to_string());
                    let silent = matches!(
                        failure,
                        ferrox_core::foxy::Failure::Io
                            | ferrox_core::foxy::Failure::Stream
                            | ferrox_core::foxy::Failure::Frame
                    );
                    if silent {
                        foxy.remember_unanswered(edge, carrier, failure);
                    }
                    if matches!(failure, ferrox_core::foxy::Failure::Rejected(429)) {
                        note_limited(&foxy.limited_strikes, &foxy.limited_until, now_secs());
                        break;
                    }
                }
            }
        }
    }
    false
}

/// CONNECT-UDP stream, HTTP/3 then HTTP/2; the pass is read fresh per dial so a renewal needs no reopen.
fn foxy_udp_dial(foxy: &FoxyOut, dest: &SocketAddr) -> Option<crate::foxy::Datagram> {
    if edge_limited(&foxy.limited_until, now_secs()) {
        return None;
    }
    for edge in ferrox_core::foxy::dial_order(
        &foxy.ladder,
        &foxy.country,
        foxy.stored.as_deref(),
        MAX_FOXY_ALTERNATES,
    ) {
        let pass = foxy
            .account
            .as_ref()
            .map_or_else(|| foxy.pass.clone(), |account| account.current());
        for carrier in crate::foxy::Carrier::udp_order() {
            // As on TCP: a silent carrier is left alone for the window, not probed per datagram.
            if foxy.carrier_unanswered(edge, carrier) {
                continue;
            }
            if carrier == crate::foxy::Carrier::H3
                && foxy
                    .upstream
                    .as_ref()
                    .is_some_and(super::foxy::UpstreamProxy::http)
            {
                continue;
            }
            let dial = crate::foxy::FoxyDial {
                host: edge.host.clone(),
                port: edge.port,
                address: foxy.edge_address,
                carrier,
                upstream: foxy.upstream.clone(),
                roots: foxy.roots.clone(),
                pins: foxy.pins.clone(),
                pass: pass.clone(),
            };
            let host = dest.ip().to_string();
            let failure = match carrier {
                crate::foxy::Carrier::H3 => {
                    let Some(lease) = crate::quic::pooled_stream_within(
                        &foxy_quic_dial(foxy, edge),
                        if foxy.carrier == crate::foxy::Carrier::H3 {
                            crate::quic::HANDSHAKE_TIMEOUT
                        } else {
                            budgets::carrier_probe()
                        },
                    ) else {
                        continue;
                    };
                    match crate::foxy::H3::open_udp(&dial, &host, dest.port(), lease) {
                        Ok(mut lane) => {
                            lane.set_read_quantum(UDP_POLL);
                            debug_lane(edge, carrier, || format!("udp opened for {dest}"));
                            clear_limited(&foxy.limited_strikes, &foxy.limited_until);
                            foxy.carrier_answered(edge, carrier);
                            return Some(crate::foxy::Datagram::H3(Box::new(lane)));
                        }
                        Err(failure) => failure,
                    }
                }
                crate::foxy::Carrier::H1 => {
                    match crate::foxy::open_udp_h1(&dial, &host, dest.port()) {
                        Ok(lane) => {
                            let _ = lane.set_read_quantum(UDP_POLL);
                            debug_lane(edge, carrier, || format!("udp opened for {dest}"));
                            clear_limited(&foxy.limited_strikes, &foxy.limited_until);
                            foxy.carrier_answered(edge, carrier);
                            return Some(crate::foxy::Datagram::H1(Box::new(lane)));
                        }
                        Err(failure) => failure,
                    }
                }
                _ => match crate::foxy::open_udp(&dial, &host, dest.port()) {
                    Ok(lane) => {
                        let _ = lane.set_read_quantum(UDP_POLL);
                        debug_lane(edge, carrier, || format!("udp opened for {dest}"));
                        clear_limited(&foxy.limited_strikes, &foxy.limited_until);
                        foxy.carrier_answered(edge, carrier);
                        return Some(crate::foxy::Datagram::H2(Box::new(lane)));
                    }
                    Err(failure) => failure,
                },
            };
            debug_lane(edge, carrier, || failure.to_string());
            if matches!(failure, ferrox_core::foxy::Failure::Rejected(429)) {
                note_limited(&foxy.limited_strikes, &foxy.limited_until, now_secs());
                break;
            }
            foxy.remember_unanswered(edge, carrier, failure);
        }
    }
    None
}

/// One local source's UDP association: its own connected uplink to the server, and the reply cipher that source seals with.
struct SsUdpClientSource {
    uplink: UdpSocket,
    hop: Option<ferrox_core::shadowsocks::Cipher>,
    last: Instant,
}

/// The outbound's plain Shadowsocks UDP lane: one sealed uplink per source, replies opened under that source's key and framed back to it.
struct SsUdpLane {
    master: ferrox_core::shadowsocks::MasterKey,
    method: ferrox_core::shadowsocks::Method,
    server: SocketAddr,
    sources: Arc<Mutex<HashMap<SocketAddr, SsUdpClientSource>>>,
    done: Arc<AtomicBool>,
    reader: RelayEnd,
}

impl SsUdpLane {
    fn open(relay: &UdpSocket, ss: &ShadowsocksOut) -> Option<Self> {
        let method = ferrox_core::shadowsocks::Method::parse(&ss.method)?;
        let master = ferrox_core::shadowsocks::MasterKey::new(&ss.password, method.key_len());
        let server: SocketAddr = format!("{}:{}", ss.address, ss.port)
            .to_socket_addrs()
            .ok()
            .and_then(|mut it| it.next())?;
        let sources = Arc::new(Mutex::new(HashMap::new()));
        let done = Arc::new(AtomicBool::new(false));
        let reader = spawn_ss_udp_sources(&sources, relay, &master, method, Arc::clone(&done))?;
        Some(Self {
            master,
            method,
            server,
            sources,
            done,
            reader,
        })
    }

    /// Seals one datagram onto its source's uplink, opening the association on the first; false only when the source map is unusable.
    fn send(
        &self,
        src: SocketAddr,
        dest: SocketAddr,
        buf: &mut [u8],
        at: usize,
        len: usize,
    ) -> bool {
        let Ok(mut guard) = self.sources.lock() else {
            return false;
        };
        let source = if let Some(source) = guard.get_mut(&src) {
            source
        } else {
            if guard.len() >= crate::shadowsocks::SS_UDP_SOURCES {
                let now = Instant::now();
                let idle = budgets::udp_idle();
                guard.retain(|_, source| now.duration_since(source.last) < idle);
                if guard.len() >= crate::shadowsocks::SS_UDP_SOURCES {
                    return true;
                }
            }
            let bound = if self.server.is_ipv6() {
                UdpSocket::bind("[::]:0")
            } else {
                UdpSocket::bind("0.0.0.0:0")
            };
            let Ok(uplink) = bound else {
                return true;
            };
            if uplink.connect(self.server).is_err() || uplink.set_nonblocking(true).is_err() {
                return true;
            }
            guard.insert(
                src,
                SsUdpClientSource {
                    uplink,
                    hop: None,
                    last: Instant::now(),
                },
            );
            let Some(source) = guard.get_mut(&src) else {
                return true;
            };
            source
        };
        source.last = Instant::now();
        if let Some(packet) = crate::shadowsocks::seal_datagram(
            &self.master,
            self.method,
            &dest,
            buf,
            at,
            len,
            &mut source.hop,
        ) {
            let _ = source.uplink.send(packet);
        }
        true
    }

    fn close(self) {
        self.done.store(true, Ordering::Relaxed);
        join(&self.reader);
    }
}

fn serve_socks_udp_shadowsocks(relay: &UdpSocket, ss: &ShadowsocksOut) {
    if let Some(method2022) = ferrox_core::shadowsocks2022::Method::parse(&ss.method) {
        serve_socks_udp_shadowsocks2022(relay, ss, method2022);
        return;
    }
    if ss.mux.udp_manager().is_some() {
        if let Some(pool) = ss.udp_pool() {
            let mut lane: Option<SsUdpLane> = None;
            let mut said = false;
            serve_socks_udp_pool(
                relay,
                &pool,
                &ss.mux,
                "shadowsocks",
                false,
                |_| true,
                |socket, src, dest, buf, at, len| {
                    if lane.is_none() {
                        let Some(open) = SsUdpLane::open(socket, ss) else {
                            if !said {
                                said = true;
                                eprintln!("shadowsocks: udp/443 skip lane unavailable; dropped");
                            }
                            return true;
                        };
                        lane = Some(open);
                    }
                    lane.as_ref()
                        .is_some_and(|lane| lane.send(src, dest, buf, at, len))
                },
            );
            if let Some(lane) = lane {
                lane.close();
            }
            return;
        }
    }
    let Some(lane) = SsUdpLane::open(relay, ss) else {
        return;
    };
    let mut buf = Vec::new();
    resize_scratch(&mut buf, crate::shadowsocks::DATAGRAM_MAX);
    while let Ok((n, src)) = relay
        .recv_from(&mut buf[crate::shadowsocks::SEAL_ROOM..crate::shadowsocks::SEAL_ROOM + UDP_BUF])
    {
        let Some((dest, payload)) =
            parse_socks_udp(&buf[crate::shadowsocks::SEAL_ROOM..crate::shadowsocks::SEAL_ROOM + n])
        else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        let (at, len) = (
            payload.as_ptr() as usize - buf.as_ptr() as usize,
            payload.len(),
        );
        if !lane.send(src, dest, &mut buf, at, len) {
            break;
        }
    }
    lane.close();
}

fn spawn_ss_udp_sources(
    sources: &Arc<Mutex<HashMap<SocketAddr, SsUdpClientSource>>>,
    relay: &UdpSocket,
    master: &ferrox_core::shadowsocks::MasterKey,
    method: ferrox_core::shadowsocks::Method,
    done: Arc<AtomicBool>,
) -> Option<RelayEnd> {
    let send = relay.try_clone().ok()?;
    let sources = Arc::clone(sources);
    let master = master.clone();
    Some(RelayPool::global().run(move || {
        let mut buf = Vec::new();
        resize_scratch(&mut buf, crate::shadowsocks::DATAGRAM_MAX);
        let room = crate::shadowsocks::SEAL_ROOM;
        let base = buf.as_ptr() as usize;
        loop {
            if done.load(Ordering::Relaxed) {
                break;
            }
            let now = Instant::now();
            let idle = budgets::udp_idle();
            let Ok(mut guard) = sources.lock() else {
                break;
            };
            guard.retain(|_, source| now.duration_since(source.last) < idle);
            for (src, source) in guard.iter_mut() {
                loop {
                    match source.uplink.recv(&mut buf[room..room + UDP_BUF]) {
                        Ok(n) => {
                            source.last = Instant::now();
                            let Some((target, payload)) = crate::shadowsocks::open_datagram(
                                &master,
                                method,
                                &mut buf[room..room + n],
                                &mut source.hop,
                            ) else {
                                continue;
                            };
                            let (at, len) = (payload.as_ptr() as usize - base, payload.len());
                            let head = 3 + if target.is_ipv6() { 19 } else { 7 };
                            let start = at - head;
                            buf[start..start + 3].fill(0);
                            crate::shadowsocks::write_addr(&mut buf[start + 3..at], &target);
                            let _ = send.send_to(&buf[start..at + len], src);
                        }
                        Err(error) if is_timeout(&error) => break,
                        Err(_) => break,
                    }
                }
            }
            drop(guard);
            std::thread::sleep(RELAY_POLL);
        }
    }))
}

/// The reply destination is the peer that first sent on this association; a later sender from another address is dropped, as the reference's `TempUDPConn` pins the ASSOCIATE peer.
fn pin_udp_source(source: &Arc<Mutex<Option<SocketAddr>>>, src: SocketAddr) -> bool {
    let Ok(mut slot) = source.lock() else {
        return false;
    };
    match *slot {
        None => {
            *slot = Some(src);
            true
        }
        Some(seen) => seen == src,
    }
}

fn serve_socks_udp_shadowsocks2022(
    relay: &UdpSocket,
    ss: &ShadowsocksOut,
    method: ferrox_core::shadowsocks2022::Method,
) {
    let Some(list) = ferrox_core::shadowsocks2022::parse_psk_list(&ss.password, method.key_len())
    else {
        return;
    };
    let psk = list.last().expect("non-empty").clone();
    let server: SocketAddr = match format!("{}:{}", ss.address, ss.port)
        .to_socket_addrs()
        .ok()
        .and_then(|mut it| it.next())
    {
        Some(server) => server,
        None => return,
    };
    let bound = if server.is_ipv6() {
        UdpSocket::bind("[::]:0")
    } else {
        UdpSocket::bind("0.0.0.0:0")
    };
    let Ok(uplink) = bound else {
        return;
    };
    if uplink.connect(server).is_err()
        || uplink.set_read_timeout(Some(budgets::udp_idle())).is_err()
    {
        return;
    }
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let done = Arc::new(AtomicBool::new(false));
    let mut datagrams = crate::shadowsocks2022::Datagrams::new();
    // The reader opens replies that echo this association's session, so it is seeded with the same session `seal` puts on the wire; a reader of its own session drops every reply as forged.
    let Some(reader) = spawn_ss_udp_reader2022(
        &uplink,
        relay,
        &psk,
        method,
        datagrams.client_session(),
        Arc::clone(&source),
        Arc::clone(&done),
    ) else {
        return;
    };
    let mut buf = udp_buffer();
    let multi = !method.is_chacha() && list.len() > 1;
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        if !pin_udp_source(&source, src) {
            continue;
        }
        if multi {
            if let Some(packet) = datagrams.seal_list(method, &list, &dest, payload) {
                let _ = uplink.send(packet);
            }
        } else if let Some(packet) = datagrams.seal(&psk, method, &dest, payload) {
            let _ = uplink.send(packet);
        }
    }
    done.store(true, Ordering::Relaxed);
    join(&reader);
}

fn spawn_ss_udp_reader2022(
    uplink: &UdpSocket,
    relay: &UdpSocket,
    psk: &[u8],
    method: ferrox_core::shadowsocks2022::Method,
    client_session: u64,
    source: Arc<Mutex<Option<SocketAddr>>>,
    done: Arc<AtomicBool>,
) -> Option<RelayEnd> {
    let read = uplink.try_clone().ok()?;
    read.set_read_timeout(Some(RELAY_POLL)).ok()?;
    let send = relay.try_clone().ok()?;
    let psk = psk.to_vec();
    Some(RelayPool::global().run(move || {
        let mut buf = udp_buffer();
        let mut reply = Vec::with_capacity(UDP_BUF);
        let mut datagrams = crate::shadowsocks2022::Datagrams::with_client_session(client_session);
        loop {
            match read.recv(&mut buf) {
                Ok(n) => {
                    let Some((target, payload)) =
                        datagrams.open_server(&psk, method, &mut buf[..n])
                    else {
                        continue;
                    };
                    let dest = match source.lock() {
                        Ok(guard) => *guard,
                        Err(_) => None,
                    };
                    let Some(dest) = dest else {
                        continue;
                    };
                    let out = socks_udp_frame(&mut reply, &target, payload);
                    let _ = send.send_to(out, dest);
                }
                Err(error) if is_timeout(&error) => {
                    if done.load(Ordering::Relaxed) {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    }))
}

fn serve_socks_udp_vmess(relay: &UdpSocket, vmess: &VmessOut) {
    if vmess.mux.udp_manager().is_some() {
        if let Some(pool) = vmess.udp_pool() {
            let mut lane: Option<VmessUdpLane> = None;
            let mut said = false;
            serve_socks_udp_pool(
                relay,
                &pool,
                &vmess.mux,
                "vmess",
                false,
                |_| true,
                |socket, src, dest, buf, at, len| {
                    if lane.is_none() {
                        let Some(open) = VmessUdpLane::new(vmess, socket) else {
                            if !said {
                                said = true;
                                eprintln!("vmess: udp/443 skip lane unavailable; dropped");
                            }
                            return true;
                        };
                        lane = Some(open);
                    }
                    lane.as_mut()
                        .is_some_and(|lane| lane.send(src, dest, &buf[at..at + len]))
                },
            );
            if let Some(lane) = lane {
                lane.close();
            }
            return;
        }
    }
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let mut uplink: Option<VmessUdpUplink> = None;
    let mut staging = Vec::with_capacity(UDP_BUF);
    let mut buf = udp_buffer();
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        if let Ok(mut slot) = source.lock() {
            *slot = Some(src);
        }
        // A reader that ended carries no more replies, so its carrier is discarded before this datagram rather than dropping the answer.
        let redial = match &uplink {
            Some(up) => {
                up.target != dest
                    || !matches!(
                        up.done.try_recv(),
                        Err(std::sync::mpsc::TryRecvError::Empty)
                    )
            }
            None => true,
        };
        if redial {
            if let Some(old) = uplink.take() {
                (old.close)();
            }
            uplink = dial_vmess_udp_uplink(vmess, &dest, relay, Arc::clone(&source));
        }
        if let Some(up) = &mut uplink {
            if !crate::vmess::write_frame(
                &mut up.write,
                &mut up.send,
                payload,
                &mut staging,
                &mut up.pad,
            ) {
                if let Some(old) = uplink.take() {
                    (old.close)();
                }
            }
        }
    }
    if let Some(old) = uplink.take() {
        (old.close)();
        join(&old.done);
    }
}

fn vless_udp_target_allowed(vless: &VlessOut, dest: &SocketAddr) -> bool {
    let allowed = !vless.is_vision() || vless.allows_udp443() || dest.port() != 443;
    if !allowed {
        static SAID: std::sync::OnceLock<()> = std::sync::OnceLock::new();
        if SAID.set(()).is_ok() {
            eprintln!(
                "vless: xtls-rprx-vision refuses UDP/443; use flow=xtls-rprx-vision-udp443 to allow it"
            );
        }
    }
    allowed
}

fn serve_socks_udp_vless(relay: &UdpSocket, vless: &VlessOut) {
    if vless.mux.udp_manager().is_some() {
        return serve_socks_udp_vless_xudp(relay, vless);
    }
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let mut uplink: Option<UdpUplink> = None;
    let mut buf = udp_buffer();
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() || !vless_udp_target_allowed(vless, &dest) {
            continue;
        }
        if let Ok(mut slot) = source.lock() {
            *slot = Some(src);
        }
        // A reader that ended carries no more replies, so its socket is discarded before this datagram rather than dropping the answer.
        let redial = match &uplink {
            Some(up) => {
                up.target != dest
                    || !matches!(
                        up.done.try_recv(),
                        Err(std::sync::mpsc::TryRecvError::Empty)
                    )
            }
            None => true,
        };
        if redial {
            if let Some(old) = uplink.take() {
                (old.close)();
            }
            uplink = dial_udp_uplink(vless, &dest, relay, Arc::clone(&source));
        }
        if let Some(up) = &mut uplink {
            if !write_udp_datagram(&mut *up.write, payload) {
                if let Some(old) = uplink.take() {
                    (old.close)();
                }
            }
        }
    }
    if let Some(old) = uplink.take() {
        (old.close)();
        join(&old.done);
    }
}

fn xudp_identity(source: SocketAddr) -> [u8; ferrox_core::mux::GLOBAL_ID] {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    let mut mix = |bytes: &[u8]| {
        for &byte in bytes {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    };
    match source.ip() {
        std::net::IpAddr::V4(ip) => mix(&ip.octets()),
        std::net::IpAddr::V6(ip) => mix(&ip.octets()),
    }
    mix(&source.port().to_be_bytes());
    hash.to_be_bytes()
}

/// One SOCKS5 UDP frame as its two parts: the head this tree builds and the payload that arrived.
/// The socket takes both by pointer, so a datagram is not gathered into a second buffer first.
pub(crate) fn socks_udp_parts<'a>(
    head: &'a mut Vec<u8>,
    target: &SocketAddr,
    payload: &'a [u8],
) -> (&'a [u8], &'a [u8]) {
    socks_udp_head(head, target);
    (head.as_slice(), payload)
}

/// One association's datagrams over the outbound's shared XUDP carrier: one flow per destination
/// whose replies land on this association's own relay, and the 443 policy applied before the mux.
fn serve_socks_udp_pool<F, G>(
    relay: &UdpSocket,
    pool: &Arc<crate::muxpool::Manager>,
    settings: &Mux,
    label: &str,
    nat: bool,
    mut allowed: F,
    mut skip: G,
) where
    F: FnMut(&SocketAddr) -> bool,
    G: FnMut(&UdpSocket, SocketAddr, SocketAddr, &mut [u8], usize, usize) -> bool,
{
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let Ok(reply) = relay.try_clone() else {
        return;
    };
    let reply = Arc::new(reply);
    let mut buf = udp_buffer();
    let mut flows: HashMap<SocketAddr, crate::muxpool::UdpFlow> = HashMap::new();
    let mut identity: Option<[u8; ferrox_core::mux::GLOBAL_ID]> = None;
    let mut published: Option<SocketAddr> = None;
    let mut said_reject = false;
    let mut said_skip = false;
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        let at = payload.as_ptr() as usize - buf.as_ptr() as usize;
        let len = payload.len();
        if len == 0 || !allowed(&dest) {
            continue;
        }
        match settings.udp_443(dest) {
            Udp443::Reject => {
                if !said_reject {
                    said_reject = true;
                    eprintln!("{label}: mux rejects udp/443; the datagram is dropped");
                }
                continue;
            }
            Udp443::Skip => {
                if !skip(relay, src, dest, &mut buf, at, len) && !said_skip {
                    said_skip = true;
                }
                continue;
            }
            Udp443::Allow => {}
        }
        if published != Some(src) {
            if let Ok(mut slot) = source.lock() {
                *slot = Some(src);
                published = Some(src);
            }
        }
        let id = if nat {
            Some(*identity.get_or_insert_with(|| xudp_identity(src)))
        } else {
            None
        };
        let target = mux_target_of(dest);
        if let Some(flow) = flows.get(&dest) {
            if !flow.send(&target, &buf[at..at + len]) {
                if let Some(old) = flows.remove(&dest) {
                    old.close();
                }
            }
            continue;
        }
        let sink_reply = Arc::clone(&reply);
        let sink_source = Arc::clone(&source);
        let deliver: crate::muxpool::Deliver = Arc::new(move |data, target| {
            let Ok(slot) = sink_source.lock() else {
                return;
            };
            let Some(peer) = *slot else {
                return;
            };
            let mut head = Vec::with_capacity(HEAD);
            let out = socks_udp_frame(&mut head, &target.unwrap_or(dest), data);
            let _ = sink_reply.send_to(out, peer);
        });
        if let Some(flow) = pool.udp(&target, id.as_ref(), &buf[at..at + len], deliver) {
            flows.insert(dest, flow);
        }
    }
    for (_, flow) in flows {
        flow.close();
    }
}

fn serve_socks_udp_vless_xudp(relay: &UdpSocket, vless: &VlessOut) {
    let Some(pool) = vless.udp_pool() else {
        return;
    };
    serve_socks_udp_pool(
        relay,
        &pool,
        &vless.mux,
        "vless",
        true,
        |dest| vless_udp_target_allowed(vless, dest),
        |_, _, _, _, _, _| true,
    );
}

fn serve_socks_udp_trojan(relay: &UdpSocket, trojan: &TrojanOut) {
    if trojan.mux.udp_manager().is_some() {
        if let Some(pool) = trojan.udp_pool() {
            let mut lane: Option<TrojanUdpLane> = None;
            serve_socks_udp_pool(
                relay,
                &pool,
                &trojan.mux,
                "trojan",
                true,
                |_| true,
                |socket, src, dest, buf, at, len| {
                    if let Some(lane) = lane.as_mut() {
                        return lane.send(src, dest, &buf[at..at + len]);
                    }
                    let Some(mut open) = TrojanUdpLane::new(trojan, socket) else {
                        return true;
                    };
                    let sent = open.send(src, dest, &buf[at..at + len]);
                    lane = Some(open);
                    sent
                },
            );
            if let Some(lane) = lane {
                lane.close();
            }
            return;
        }
    }
    let source: Arc<Mutex<Option<SocketAddr>>> = Arc::new(Mutex::new(None));
    let mut uplink: Option<TrojanUdpUplink> = None;
    let mut buf = udp_buffer();
    let mut trojan_head = Vec::with_capacity(32);
    while let Ok((n, src)) = relay.recv_from(&mut buf) {
        let Some((dest, payload)) = parse_socks_udp(&buf[..n]) else {
            continue;
        };
        if payload.is_empty() {
            continue;
        }
        if matches!(trojan.mux.udp_443(dest), Udp443::Reject) {
            continue;
        }
        if let Ok(mut slot) = source.lock() {
            *slot = Some(src);
        }
        if uplink.is_none() {
            uplink = dial_trojan_udp_uplink(trojan, &dest, relay, Arc::clone(&source));
        }
        if let Some(up) = &mut uplink {
            if !write_trojan_datagram(&mut *up.write, &dest, payload, &mut trojan_head) {
                if let Some(old) = uplink.take() {
                    (old.close)();
                }
            }
        }
    }
    if let Some(old) = uplink.take() {
        (old.close)();
        join(&old.done);
    }
}

/// The pooled dial uses the edge's name, not its resolved address, so a country's flows share one connection.
fn foxy_quic_dial(foxy: &FoxyOut, edge: &ferrox_core::foxy::Candidate) -> crate::quic::QuicDial {
    crate::quic::QuicDial {
        id: [0; 16],
        host: std::sync::Arc::clone(&edge.host),
        address: std::sync::Arc::clone(&edge.host),
        port: edge.port,
        upstream: foxy.upstream.clone(),
        roots: Some(foxy.roots.clone()),
        ech_config_list: None,
    }
}

pub(crate) fn relay_tunnel(
    client: &Connection,
    tunnel: &std::sync::Arc<std::sync::Mutex<crate::foxy::Tunnel>>,
) {
    let Ok(mut client_read) = client.try_clone() else {
        return;
    };
    let Ok(mut client_write) = client.try_clone() else {
        return;
    };
    let forward_tunnel = std::sync::Arc::clone(tunnel);
    let backward_tunnel = std::sync::Arc::clone(tunnel);
    // One flag per leg, read by the other: a flow whose client said goodbye keeps its lane, its stream and both threads for the life of the process otherwise, and a quantum-bounded read is what lets a parked leg hear about it.
    let forward_ended = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let backward_ended = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let (report_forward, learn_backward) = (
        std::sync::Arc::clone(&forward_ended),
        std::sync::Arc::clone(&backward_ended),
    );
    let forward = move || {
        // The park's grain, armed on the read handle: a stack that leaves a blocking read asleep through a shutdown still ends it on its own timeout, and the read after that sees the closed socket.
        let _ = client_read.set_read_timeout(Some(budgets::relay_quantum()));
        copy_locked(&mut client_read, &forward_tunnel, true, &learn_backward);
        // The client's half ended, so the tunnel's ends too: h2 keeps the session for the next flow only when both halves of the stream are closed.
        if let Ok(mut lane) = forward_tunnel.lock() {
            let _ = lane.finish();
        }
        report_forward.store(true, std::sync::atomic::Ordering::Release);
    };
    let done = RelayPool::global().run(forward);
    copy_locked(&mut client_write, &backward_tunnel, false, &forward_ended);
    backward_ended.store(true, std::sync::atomic::Ordering::Release);
    // Both halves, because the other leg is parked in a blocking read on this socket: a FIN on the write half alone leaves the parked reader asleep and the flow's worker lost for the life of the process.
    let _ = client_write.shutdown(Shutdown::Both);
    join(&done);
}

fn copy_locked(
    socket: &mut Connection,
    tunnel: &std::sync::Arc<std::sync::Mutex<crate::foxy::Tunnel>>,
    forward: bool,
    peer_ended: &std::sync::atomic::AtomicBool,
) {
    const CHUNK: usize = 16 * 1024;
    let direction = if forward { "forward" } else { "backward" };
    let started = crate::foxy::debug_on().then(Instant::now);
    let mut buf = [0u8; CHUNK];
    let mut total = 0u64;
    let mut sleeps = 0u32;
    loop {
        let moved = if forward {
            match socket.read(&mut buf) {
                Ok(0) => {
                    debug_relay(direction, total, sleeps, None);
                    break;
                }
                Err(error)
                    if matches!(
                        error.kind(),
                        std::io::ErrorKind::WouldBlock
                            | std::io::ErrorKind::TimedOut
                            | std::io::ErrorKind::Interrupted
                    ) =>
                {
                    // The quantum expired on a client that has not spoken: idle, unless the lane's own leg has already ended.
                    if peer_ended.load(std::sync::atomic::Ordering::Acquire) {
                        debug_relay(direction, total, sleeps, None);
                        break;
                    }
                    continue;
                }
                Err(error) => {
                    debug_relay(direction, total, sleeps, Some(error.kind()));
                    break;
                }
                // A short write is credit, not completion: the rest retries once the window reopens.
                Ok(read) => {
                    if total == 0 {
                        debug_bytes(direction, &buf[..read], started);
                    }
                    write_full(tunnel, peer_ended, &buf[..read])
                }
            }
        } else {
            // The lane is handed back before the client is written: a client that has stopped reading would otherwise cost the other direction its turn on the lane, and an upload that cannot start cannot finish the request it waits on.
            let taken = {
                let Ok(mut lane) = tunnel.lock() else {
                    break;
                };
                census!("tunnel-leg-read", crate::census::NO_FD, None);
                match lane.read(&mut buf) {
                    Ok(0) => {
                        debug_relay(direction, total, sleeps, None);
                        break;
                    }
                    Ok(read) => read,
                    // No payload in the quantum: drop the lock so the writer gets a turn.
                    Err(error)
                        if matches!(
                            error.kind(),
                            std::io::ErrorKind::WouldBlock
                                | std::io::ErrorKind::TimedOut
                                | std::io::ErrorKind::Interrupted
                        ) =>
                    {
                        // The lane has not answered inside its quantum: idle, unless the client's own leg has ended and nothing is left to deliver.
                        if peer_ended.load(std::sync::atomic::Ordering::Acquire) {
                            debug_relay(direction, total, sleeps, None);
                            break;
                        }
                        // The wait belongs outside the lock, on the edge socket rather than on a clock: a leg parked on a quiet edge would otherwise cost the first uplink byte after a pause the whole of its wait, and a leg that sleeps instead of watching the socket pays that pause in the other direction too.
                        if let Some((edge, park)) = lane.read_wait() {
                            drop(lane);
                            census!("downlink-park", crate::census::handle(&edge), Some(park));
                            let _ = edge.wait_readable(park);
                        } else {
                            drop(lane);
                            sleeps += 1;
                            std::thread::sleep(RELAY_IDLE);
                        }
                        continue;
                    }
                    Err(error) => {
                        debug_relay(direction, total, sleeps, Some(error.kind()));
                        break;
                    }
                }
            };
            if total == 0 {
                debug_bytes(direction, &buf[..taken], started);
            }
            let written = {
                census!("tunnel-leg-write", crate::census::handle(socket), None);
                socket.write_all(&buf[..taken])
            };
            match written {
                Ok(()) => taken,
                Err(error) => {
                    debug_relay(direction, total, sleeps, Some(error.kind()));
                    break;
                }
            }
        };
        total += moved as u64;
        if moved == 0 {
            debug_relay(direction, total, sleeps, None);
            break;
        }
    }
}

/// Writes all bytes through the shared lane, taking the lock per call so the other direction interleaves.
fn write_full(
    tunnel: &std::sync::Arc<std::sync::Mutex<crate::foxy::Tunnel>>,
    peer_ended: &std::sync::atomic::AtomicBool,
    mut buf: &[u8],
) -> usize {
    let total = buf.len();
    while !buf.is_empty() {
        let Ok(mut lane) = tunnel.lock() else {
            break;
        };
        let stalled = match lane.write(buf) {
            Ok(0) => true,
            Ok(wrote) => {
                buf = &buf[wrote..];
                false
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock
                        | std::io::ErrorKind::TimedOut
                        | std::io::ErrorKind::Interrupted
                ) =>
            {
                true
            }
            Err(_) => break,
        };
        if stalled {
            drop(lane);
            // A closed window answers before the socket is touched, so the lane cannot report its own death here: the leg that carried the other way has to say so.
            if peer_ended.load(std::sync::atomic::Ordering::Acquire) {
                break;
            }
            std::thread::sleep(RELAY_IDLE);
        }
    }
    total - buf.len()
}

#[cfg(test)]
fn relay(client: &Connection, target: &Connection) {
    let Ok(client_read) = client.try_clone() else {
        return;
    };
    let Ok(target_read) = target.try_clone() else {
        return;
    };
    let Ok(target_write) = target.try_clone() else {
        return;
    };
    let Ok(client_write) = client.try_clone() else {
        return;
    };
    // A descriptor fast path cannot cross the mask, so a masked stream keeps the buffered copy.
    if !target_write.masked() && !client_write.masked() && poll_available() {
        #[cfg(target_os = "linux")]
        let (first, second) =
            poll_handoff(client_read, target_write, target_read, client_write, None);
        #[cfg(not(target_os = "linux"))]
        let (first, second) = poll_handoff(client_read, target_write, target_read, client_write);
        join(&first);
        join(&second);
        return;
    }
    relay_owned(client_read, target_write, target_read, client_write, None);
}

/// Hand a flow to the readiness workers and return: the accepted connection's thread is done
/// with the flow once its socket descriptors belong to the workers, which is what keeps the
/// thread count a property of the machine rather than of the flow count.
pub(crate) fn relay_handoff(client: &Connection, target: &Connection) {
    relay_handoff_with(client, target, None);
}

/// The success and refusal a lazy VLESS answer reports: the rung counts useful only when the header validates.
struct AnswerHooks {
    success: Box<dyn FnOnce() + Send>,
    refused: Arc<dyn Fn() + Send + Sync>,
}

/// The same hand-off for a VLESS dial that has not seen the answer: the reply lane strips
/// `[0, 0]` on the read that first carries it, so an upload-only flow relays at once and a
/// server that withholds its answer holds no thread or wait of the dial's.
fn relay_handoff_answering(
    client: &Connection,
    target: &Connection,
    success: Box<dyn FnOnce() + Send>,
    refused: Arc<dyn Fn() + Send + Sync>,
) {
    relay_handoff_with(client, target, Some(AnswerHooks { success, refused }));
}

fn relay_handoff_with(client: &Connection, target: &Connection, answer: Option<AnswerHooks>) {
    let Ok(client_read) = client.try_clone() else {
        return;
    };
    let Ok(target_read) = target.try_clone() else {
        return;
    };
    let Ok(target_write) = target.try_clone() else {
        return;
    };
    let Ok(client_write) = client.try_clone() else {
        return;
    };
    // Windows' readiness wakeup costs more than the copy: two blocking legs match the comparator and park in the kernel instead of polling.
    #[cfg(windows)]
    if answer.is_none()
        && !target_write.masked()
        && !client_write.masked()
        && !client_read.metered()
        && !target_read.metered()
    {
        relay_vectored_direct(client_read, target_write, target_read, client_write);
        return;
    }
    // A descriptor fast path cannot cross the mask, and only the Linux pump strips the answer the raw VLESS dial has not seen; every other host and a metered leg keep the lane pool.
    #[cfg(target_os = "linux")]
    let fast = !target_write.masked()
        && !client_write.masked()
        && !client_read.metered()
        && !target_read.metered()
        && poll_available();
    #[cfg(not(target_os = "linux"))]
    let fast = answer.is_none()
        && !target_write.masked()
        && !client_write.masked()
        && !client_read.metered()
        && !target_read.metered()
        && poll_available();
    if fast {
        #[cfg(target_os = "linux")]
        let _ends = poll_handoff(client_read, target_write, target_read, client_write, answer);
        #[cfg(not(target_os = "linux"))]
        let _ends = poll_handoff(client_read, target_write, target_read, client_write);
        return;
    }
    // A masked or metered leg needs the buffered copy, and a host without a descriptor pump keeps the lane pool.
    relay_lanes(client_read, target_write, target_read, client_write, answer);
}

/// One direction of a TCP relay as a lane step: the descriptor pump's buffer and nonblocking
/// shape, but the wait is handed back to the lane and the flow's sibling, not slept in.
fn relay_lanes(
    client_read: Connection,
    target_write: Connection,
    target_read: Connection,
    client_write: Connection,
    answer: Option<AnswerHooks>,
) {
    // A pool with no worker would run forward inline before reply was queued, so use the owned copy.
    if !lane_pool::start() {
        relay_owned(client_read, target_write, target_read, client_write, answer);
        return;
    }
    for connection in [&client_read, &target_read, &target_write, &client_write] {
        let _ = connection.set_read_timeout(Some(RELAY_POLL));
        let _ = connection.set_write_timeout(Some(RELAY_POLL));
    }
    let forward_stall = client_read
        .policy()
        .or_else(|| target_write.policy())
        .and_then(|flow| flow.conn_idle())
        .unwrap_or_else(crate::budgets::relay_stall);
    let reply_stall = target_read
        .policy()
        .or_else(|| client_write.policy())
        .and_then(|flow| flow.conn_idle())
        .unwrap_or_else(crate::budgets::relay_stall);
    let close: Arc<dyn Fn() + Send + Sync> = Arc::new(|| {});
    let flow = RelayFinish::new(false, close, None);
    let first = Arc::clone(&flow);
    let mut forward = TcpCopy::new(client_read, target_write);
    forward.stall = forward_stall;
    forward.reply_idle = forward_stall;
    lane_pool::submit(
        Box::new(move || forward.step(&first)),
        Box::new({
            let flow = Arc::clone(&flow);
            move || {
                flow.mark_ended();
                flow.lane_done();
            }
        }),
    );
    let second = Arc::clone(&flow);
    let mut reply = TcpCopy::new(target_read, client_write);
    reply.stall = reply_stall;
    reply.reply_idle = reply_stall;
    if let Some(answer) = answer {
        reply = reply.answering(answer);
    }
    lane_pool::submit(
        Box::new(move || reply.step(&second)),
        Box::new({
            let flow = Arc::clone(&flow);
            move || {
                flow.mark_ended();
                flow.lane_done();
            }
        }),
    );
}

struct TcpCopy {
    src: Connection,
    dst: Connection,
    bytes: Vec<u8>,
    filled: usize,
    off: usize,
    eof: bool,
    ended: bool,
    stalled: Option<std::time::Instant>,
    stall: Duration,
    reply_idle: Duration,
    /// The VLESS answer this lane strips before its first payload byte: a server may hold
    /// `[0, 0]` until it sees payload, so the strip waits on the read, not before the relay.
    answer: crate::vision::Answer,
    success: Option<Box<dyn FnOnce() + Send>>,
    refused: Option<Arc<dyn Fn() + Send + Sync>>,
}

impl TcpCopy {
    fn new(src: Connection, dst: Connection) -> Self {
        Self {
            src,
            dst,
            bytes: RelayBuf::with_len(RELAY_BUFFER).into_vec(),
            filled: 0,
            off: 0,
            eof: false,
            ended: false,
            stalled: None,
            stall: crate::budgets::relay_stall(),
            reply_idle: crate::budgets::RELAY_RESPONSE_IDLE,
            answer: crate::vision::Answer::None,
            success: None,
            refused: None,
        }
    }

    fn answering(mut self, hooks: AnswerHooks) -> Self {
        self.answer = crate::vision::Answer::Pending {
            head: [0; 2],
            filled: 0,
        };
        self.success = Some(hooks.success);
        self.refused = Some(hooks.refused);
        self
    }

    fn refuse(&mut self) {
        if let Some(refused) = self.refused.take() {
            refused();
        }
        self.answer = crate::vision::Answer::None;
    }

    /// The answer a lane owes before its first payload byte: `None` once it is stripped, so
    /// the step reads payload, and the terminal step when the peer refused or closed.
    fn strip_answer(&mut self, flow: &Arc<RelayFinish>) -> Option<Next> {
        let crate::vision::Answer::Pending { head, filled } = self.answer else {
            return None;
        };
        let mut head = head;
        let mut filled = usize::from(filled);
        while filled < 2 {
            match self.src.read(&mut head[filled..]) {
                Ok(0) => {
                    self.refuse();
                    self.abandon();
                    return Some(Next::Done);
                }
                Ok(n) => filled += n,
                Err(error) if is_timeout(&error) => {
                    self.answer = crate::vision::Answer::Pending {
                        head,
                        filled: filled as u8,
                    };
                    if flow.ended() && flow.ended_and_idle(self.reply_idle) {
                        self.refuse();
                        self.end();
                        return Some(Next::Done);
                    }
                    return Some(Next::Idle);
                }
                Err(_) => {
                    self.refuse();
                    self.abandon();
                    return Some(Next::Done);
                }
            }
        }
        if ferrox_core::vless::VlessLink::decode_response_header(&head).is_err() {
            self.refuse();
            self.abandon();
            return Some(Next::Done);
        }
        self.answer = crate::vision::Answer::None;
        self.refused = None;
        flow.mark_progress();
        self.reply_idle = crate::budgets::RELAY_RESPONSE_IDLE;
        if let Some(success) = self.success.take() {
            success();
        }
        None
    }

    fn step(&mut self, flow: &Arc<RelayFinish>) -> Next {
        if self.ended {
            return Next::Done;
        }
        while self.off < self.filled {
            match self.dst.write(&self.bytes[self.off..self.filled]) {
                Ok(0) => {
                    self.end();
                    return Next::Done;
                }
                Ok(n) => {
                    self.off += n;
                    self.stalled = None;
                    if self.off < self.filled {
                        return Next::Retry;
                    }
                }
                Err(error) if is_timeout(&error) => {
                    let now = std::time::Instant::now();
                    let since = *self.stalled.get_or_insert(now);
                    if now.duration_since(since) >= self.stall {
                        self.abandon();
                        return Next::Done;
                    }
                    return Next::Idle;
                }
                Err(_) => {
                    self.end();
                    return Next::Done;
                }
            }
        }
        self.off = 0;
        self.filled = 0;
        self.stalled = None;
        if self.eof {
            self.end();
            return Next::Done;
        }
        if let Some(next) = self.strip_answer(flow) {
            return next;
        }
        match self.src.read(&mut self.bytes) {
            Ok(0) => {
                self.eof = true;
                self.end();
                Next::Done
            }
            Ok(n) => {
                self.filled = n;
                Next::More
            }
            Err(error) if is_timeout(&error) => {
                note_wait_fd(wait_key(&self.src));
                note_wait_idle(self.reply_idle);
                note_wait_finish(flow);
                if flow.ended() && flow.ended_and_idle(self.reply_idle) {
                    self.end();
                    Next::Done
                } else {
                    Next::Idle
                }
            }
            Err(_) => {
                self.end();
                Next::Done
            }
        }
    }

    fn end(&mut self) {
        if self.ended {
            return;
        }
        self.ended = true;
        self.stalled = None;
        let _ = self.dst.shutdown(Shutdown::Write);
    }

    fn abandon(&mut self) {
        self.ended = true;
        self.stalled = None;
        let _ = self.src.shutdown(Shutdown::Both);
        let _ = self.dst.shutdown(Shutdown::Both);
    }
}

#[cfg(target_os = "linux")]
