        let mut early = [0u8; 4];
        client.read_exact(&mut early).expect("early bytes");
        assert_eq!(&early, b"boot");
        client.write_all(b"ping").expect("writes");
        let mut back = [0u8; 4];
        client.read_exact(&mut back).expect("echoes");
        assert_eq!(&back, b"ping");
        drop(client);
        server.join().expect("server joins");
